const supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_ANON_KEY);
const SUPABASE_SERVICE_ROLE_KEY = readSecretEnv('SUPABASE_SERVICE_ROLE_KEY');
const jobMailSupabase = SUPABASE_SERVICE_ROLE_KEY
    ? createClient(process.env.SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, { auth:{ persistSession:false, autoRefreshToken:false } })
    : null;
// Không làm crash toàn bot nếu máy chủ chưa có secret JOB MAIL. Chỉ khóa riêng JOB MAIL và ghi chẩn đoán
// vào server log; tuyệt đối không log giá trị key và không fallback sang ANON.
if (!SUPABASE_SERVICE_ROLE_KEY) {
    console.error('❌ JOB MAIL CONFIG: thiếu SUPABASE_SERVICE_ROLE_KEY trong environment của tiến trình Node.js. Hãy cấu hình biến này trên máy chủ rồi restart bot/service.');
}
function jobMailDb() {
    if (jobMailSupabase) return jobMailSupabase;
    const error = new Error('JOB MAIL chưa được cấu hình database client riêng trên máy chủ.');
    error.code = 'JOB_MAIL_SERVICE_ROLE_MISSING';
    throw error;
}

// ==================== TƯƠNG THÍCH SCHEMA SUPABASE (CHỐNG MẤT DỮ LIỆU) ====================
// NGUYÊN NHÂN LỖI 42703 (ví dụ "column users.quizDate does not exist" hoặc field nghiệp vụ chưa có cột thật):
// code ghi/đọc một số cột mà bảng "users" trên Supabase thật KHÔNG có. Postgres từ chối TOÀN BỘ câu lệnh
// đó, nên chỉ cần 1 cột thiếu là mất luôn cả lần lưu coin/đơn hàng/nhiệm vụ -> chính là lỗi "mất dữ liệu".
// CÁCH SỬA: lúc chạy, đọc danh sách cột THẬT của bảng users; cột nào có thật thì ghi thẳng vào users,
// cột nào chưa có thì lưu an toàn vào bảng app_settings (khóa user_extra_state) và ghép lại khi đọc user.
// Nhờ vậy các field linh hoạt của users không bị mất khi thiếu cột; riêng schema nghiệp vụ như LINK TASK/JOB MAIL vẫn phải chạy migration SQL tương ứng.
// ==================== MỐC NGÀY THEO GIỜ VIỆT NAM (0h00) ====================
// Mọi giới hạn theo ngày (nhiệm vụ, câu hỏi, SmartLink, rút tiền) đều tính theo 0h00 giờ Việt Nam,
// KHÔNG phụ thuộc giờ máy chủ hay giờ điện thoại (trước đây dùng giờ thiết bị nên chỉnh giờ máy
// hoặc tải lại app là có thêm lượt).
function vietnamDayKey(date = new Date()) {
    return new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Ho_Chi_Minh', year: 'numeric', month: '2-digit', day: '2-digit'
    }).format(date);
}
function isCurrentVietnamDay(value) {
    if (!value) return false;
    const today = vietnamDayKey();
    if (value === today) return true;
    const parsed = new Date(value);
    return !Number.isNaN(parsed.getTime()) && vietnamDayKey(parsed) === today;
}
function vietnamDayStartIso(date = new Date()) {
    return `${vietnamDayKey(date)}T00:00:00+07:00`;
}
function vietnamTimeText(date = new Date()) {
    const dayPart = new Intl.DateTimeFormat('vi-VN', {
        timeZone: 'Asia/Ho_Chi_Minh', day: '2-digit', month: '2-digit', year: 'numeric'
    }).format(date);
    const timePart = new Intl.DateTimeFormat('vi-VN', {
        timeZone: 'Asia/Ho_Chi_Minh', hour: '2-digit', minute: '2-digit', hour12: false
    }).format(date);
    return `${dayPart} ${timePart}`;
}
// Các field được đưa về 0 khi sang ngày mới (0h00 giờ Việt Nam)
function dailyResetFields() {
    return {
        adsToday: 0, smartlinksToday: 0, bonusAdsToday: 0, rewardedAdsToday: 0, extraDeliveryAdsToday: 0, extraDeliveryCount: 0,
        passiveAdsToday: 0, passiveAdsDayKey: vietnamDayKey(), passiveAdNextAllowedAt: 0,
        dailyValidInvites: 0,
        deliveryCount: 0, smartlinkCount: 0, usedSmartlinks: [],
        spinAdCount: 0, spinAdProgress: 0, chestOpensToday: 0,
        quizDate: vietnamDayKey(), quizFreeUsed: false, quizAdUnlocked: 0, quizUsedIds: [],
        dailyTasks: null, allTasksClaimed: false, withdrawRemain: 1,
        lastResetDate: vietnamDayKey()
    };
}

// ==================== PHẦN THƯỞNG REFERRAL — CODE/SERVER LÀ NGUỒN CHUẨN ====================
const INSTANT_REF_COINS = 1000;
const INSTANT_REF_ORDERS = 2000;
const REFERRAL_MILESTONE_REWARDS = Object.freeze([
    Object.freeze({ friends:1, coins:500, orders:0, spins:1 }),
    Object.freeze({ friends:3, coins:1000, orders:500, spins:0 }),
    Object.freeze({ friends:5, coins:1500, orders:1000, spins:1 }),
    Object.freeze({ friends:10, coins:2500, orders:2000, spins:2 }),
    Object.freeze({ friends:20, coins:4000, orders:3000, spins:3 }),
    Object.freeze({ friends:30, coins:6000, orders:5000, spins:3 }),
    Object.freeze({ friends:50, coins:10000, orders:7000, spins:5 }),
    Object.freeze({ friends:75, coins:15000, orders:10000, spins:7 }),
    Object.freeze({ friends:100, coins:20000, orders:15000, spins:10 })
]);

function parseReferralMilestones(value) {
    if (Array.isArray(value)) return value;
    if (typeof value === 'string' && value) {
        try { const parsed = JSON.parse(value); return Array.isArray(parsed) ? parsed : []; } catch (_) { return []; }
    }
    return [];
}
function referralMilestoneClaimMap(userRow = {}, extra = {}) {
    const claims = {};
    for (const item of parseReferralMilestones(userRow.referralMilestones)) {
        if (item && Number.isFinite(Number(item.friends)) && item.claimed === true) claims[String(Number(item.friends))] = true;
    }
    const serverClaims = extra?.serverReferralMilestones;
    if (serverClaims && typeof serverClaims === 'object' && !Array.isArray(serverClaims)) {
        for (const [friends, claimed] of Object.entries(serverClaims)) if (claimed === true) claims[String(Number(friends))] = true;
    }
    return claims;
}
function referralMilestoneRewardText(reward, language = 'vi') {
    const en = normalizeUserLanguage(language) === 'en';
    const parts = [];
    if (Number(reward?.coins || 0) > 0) parts.push(`${Number(reward.coins).toLocaleString(en ? 'en-US' : 'vi-VN')} ${en ? 'Coins' : 'Coin'}`);
    if (Number(reward?.orders || 0) > 0) parts.push(`${Number(reward.orders).toLocaleString(en ? 'en-US' : 'vi-VN')} ${en ? 'Orders' : 'Đơn Hàng'}`);
    if (Number(reward?.spins || 0) > 0) parts.push(`${Number(reward.spins).toLocaleString(en ? 'en-US' : 'vi-VN')} ${en ? 'Chest Opens' : 'Lượt Mở Rương'}`);
    return parts.join(' + ');
}
function canonicalReferralMilestones(claims = {}) {
    return REFERRAL_MILESTONE_REWARDS.map(reward => ({
        ...reward,
        reward: referralMilestoneRewardText(reward, 'vi'),
        claimed: claims[String(reward.friends)] === true
    }));
}

const NEW_USER_WELCOME_COINS = 300;
const NEW_USER_WELCOME_ORDERS = 300;
const NEW_USER_TUTORIAL_AD_GOAL = 3;
const NEW_USER_TUTORIAL_SMARTLINK_GOAL = 2;
const PASSIVE_AD_DAILY_LIMIT = 7;
const PASSIVE_AD_MIN_COOLDOWN_MS = 3 * 60 * 1000;
const PASSIVE_AD_MAX_COOLDOWN_MS = 5 * 60 * 1000;
const PASSIVE_AFTER_MANUAL_MS = 3 * 60 * 1000;
function randomPassiveCooldownMs() {
    return PASSIVE_AD_MIN_COOLDOWN_MS + crypto.randomInt(PASSIVE_AD_MAX_COOLDOWN_MS - PASSIVE_AD_MIN_COOLDOWN_MS + 1);
}
function newUserFeatureState() {
    return {
        newUserWelcomeEligible: true,
        newUserWelcomeClaimed: false,
        newUserWelcomeClaimedAt: null,
        newUserWelcomePayoutId: null,
        newUserTutorialEligible: true,
        newUserTutorialCompleted: false,
        newUserTutorialRewardClaimed: false,
        newUserTutorialRewardClaimedAt: null,
        newUserTutorialPayoutId: null,
        newUserTutorialBaseAds: 0,
        newUserTutorialBaseSmartlinks: 0,
        passiveAdsToday: 0,
        passiveAdsDayKey: vietnamDayKey(),
        passiveAdNextAllowedAt: 0,
        lastManualRewardedCompletedAt: 0,
        lastPassiveAdToken: ''
    };
}

const USER_EXTRA_KEY = 'user_extra_state';
const CORE_USER_COLUMNS = ['id', 'name', 'coins', 'orders', 'spins', 'truckLevel', 'isBanned', 'walletUpdatedAt'];
let userColumnsCache = null;
let userColumnsAt = 0;
async function getUserColumns(forceRefresh = false) {
    if (!forceRefresh && userColumnsCache && Date.now() - userColumnsAt < 5 * 60 * 1000) return userColumnsCache;
    try {
        const { data, error } = await supabase.from('users').select('*').limit(1);
        if (error) throw error;
        if (Array.isArray(data) && data.length > 0) {
            userColumnsCache = new Set(Object.keys(data[0]));
            userColumnsAt = Date.now();
            return userColumnsCache;
        }
    } catch (e) {
        console.error('Không đọc được danh sách cột bảng users:', e.message);
    }
    if (!userColumnsCache) { userColumnsCache = new Set(CORE_USER_COLUMNS); userColumnsAt = Date.now(); }
    return userColumnsCache;
}

// Bộ nhớ đệm cho phần dữ liệu lưu ngoài bảng users: đọc tức thì, ghi gộp mỗi 3 giây để không
// nặng database và không có 2 request nào ghi đè mất dữ liệu của nhau.
