bot.command('mailsearch', async (ctx) => {
    if (!isAdmin(ctx)) return;
    const query = String(ctx.message?.text || '').replace(/^\/mailsearch(?:@\w+)?\s*/i,'').trim();
    if (!query) return ctx.reply('❌ Sử dụng: /mailsearch <Gmail hoặc User ID>');
    try {
        let db = jobMailDb().from('job_mails').select('id,email_original,user_id,username,status,reject_reason,submitted_at,reviewed_at,reviewed_by,reward_orders').order('submitted_at',{ascending:false}).limit(10);
        if (JOB_MAIL_EMAIL_REGEX.test(query)) db = db.eq('email_normalized', normalizeJobMailEmail(query));
        else db = db.eq('user_id', query);
        const { data, error } = await db;
        if (error) throw error;
        if (!data?.length) return ctx.reply('📭 Không tìm thấy JOB MAIL phù hợp.');
        const text = data.map(m => `📧 ${m.email_original}\n👤 User: ${m.user_id}${m.username ? ` (@${String(m.username).replace(/^@/,'')})` : ''}\n📌 Trạng thái: ${jobMailStatusLabel(m.status)}\n🕐 Gửi lúc: ${vietnamTimeText(new Date(m.submitted_at))}\n${m.reviewed_at ? `✅/❌ Xử lý lúc: ${vietnamTimeText(new Date(m.reviewed_at))}\n` : ''}${m.reject_reason ? `📝 Lý do: ${m.reject_reason}\n` : ''}#${m.id}`).join('\n\n━━━━━━━━━━━━\n\n');
        return ctx.reply(text.slice(0,3900));
    } catch (e) {
        console.error('/mailsearch:',e);
        return ctx.reply(jobMailDbUnavailable(e) ? jobMailSetupMessage(e) : `❌ Lỗi tìm kiếm: ${e.message}`);
    }
});

