// Lấy userId của người gọi API, thử nhiều nguồn khác nhau (query, body, hoặc đoạn cuối path dạng /api/xxx/:id)
function extractRequestUserId(req) {
    return req.query?.userId || req.body?.userId || req.body?.id || req.path.split('/').filter(Boolean).pop();
}

// Chặn toàn bộ API của Mini App khi bot đang bị khoá bảo trì (trừ chính API kiểm tra khoá ở trên, các API
// dành cho Admin, và mọi request đến từ chính Admin CHÍNH - ID 6327666718 - để Admin luôn thao tác được
// bình thường qua Mini App/web /admin trong lúc bảo trì).
app.use('/api', (req, res, next) => {
    // Attempt đã được phát trước lúc bảo trì vẫn phải đi tới landing để ghi nhận "landed" và hiện mã.
    // Chỉ whitelist GET landing; /link-task/start và /link-task/verify-code vẫn bị khóa khi BOT_LOCKED.
    const isLinkTaskLanding = req.method === 'GET' && (/^\/link-task\/landing\/[^/]+$/.test(req.path) || /^\/link-task\/provider-fallback\/[^/]+$/.test(req.path));
    if (BOT_LOCKED && req.path !== '/lock-status' && !req.path.startsWith('/admin') && !isLinkTaskLanding) {
        if (String(extractRequestUserId(req)) === String(ADMIN_ID)) return next();
        return res.status(503).json({ locked: true, error: MAINTENANCE_MESSAGE, message: MAINTENANCE_MESSAGE });
    }
    next();
});

// API legacy giữ tương thích: trả marker ONBOARDING PERSISTENT, không live-check membership.
app.get('/api/verify/:id', async (req, res) => {
    try {
        const userId = String(req.params.id || '');
        if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,verified:false,error:'Telegram session không hợp lệ.'});
        const onboarding = await getOnboardingAccessState(userId);
        if (!onboarding.exists) return res.status(404).json({success:false,verified:false,error:'User not found'});
        if (onboarding.reliable === false) return res.status(503).json({success:false,verified:false,retry:true,error:'Không đọc được trạng thái onboarding.'});
        res.set('Cache-Control','no-store');
        return res.json({success:onboarding.verified,verified:onboarding.verified,onboardingGroupsVerified:onboarding.verified,verifiedAt:onboarding.verifiedAt||null,legacy:onboarding.legacy});
    } catch (e) {
        console.error('Lỗi API verify persistent:', e);
        return res.status(500).json({success:false,verified:false,error:'Không đọc được trạng thái onboarding.'});
    }
});

// API lưu IP — chỉ dùng IP server quan sát được, không tin req.body.ip.
app.post('/api/save-ip/:id', async (req, res) => {
    const userId=String(req.params.id||'');
    if (!assertTelegramUser(req,userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if (!requireTelegramMobile(req,res)) return;
    const ip=requestIp(req);
    if (!ip) return res.status(400).json({success:false,error:'Không xác định được IP.'});
    const {data:userBeforeUpdate,error:fetchError}=await readUserRow(userId);
    if (!userBeforeUpdate) {
        if (fetchError) console.error('Lỗi lấy user để lưu IP:',fetchError.message);
        return res.status(404).json({success:false,error:'User not found'});
    }
    if (String(userBeforeUpdate.ip||'')!==ip) {
        const {error:updateError}=await saveUserFields(userId,{ip});
        if (updateError) return res.status(500).json({success:false,error:'Failed to update IP'});
    }
    if (String(userBeforeUpdate.ip||'')!==ip) {
        const duplicates=await checkDuplicateIP(userId,ip);
        if (duplicates.length>0) {
            await safeSendMessage(ADMIN_ID,
                `⚠️ *CẢNH BÁO IP TRÙNG MỚI PHÁT HIỆN!*
👤 User: ${userBeforeUpdate.name||'N/A'} (${userId})
🌐 IP: ${ip}
⚠️ Trùng với: ${duplicates.map(d=>`${d.name} (${d.id})`).join(', ')}`,
                {parse_mode:'Markdown'});
        }
    }
    return res.json({success:true});
});

function newUserTutorialStatusFromRow(user = {}) {
    const eligible = user.newUserTutorialEligible === true;
    const adBase = Math.max(0, Number(user.newUserTutorialBaseAds || 0));
    const smartBase = Math.max(0, Number(user.newUserTutorialBaseSmartlinks || 0));
    const ads = eligible ? Math.max(0, Math.min(NEW_USER_TUTORIAL_AD_GOAL, Number(user.lifetimeAdsWatched || 0) - adBase)) : 0;
    const smartlinks = eligible ? Math.max(0, Math.min(NEW_USER_TUTORIAL_SMARTLINK_GOAL, Number(user.lifetimeSmartlinks || 0) - smartBase)) : 0;
    const completed = eligible && (user.newUserTutorialCompleted === true || (ads >= NEW_USER_TUTORIAL_AD_GOAL && smartlinks >= NEW_USER_TUTORIAL_SMARTLINK_GOAL));
    return {
        eligible,
        ads, adGoal:NEW_USER_TUTORIAL_AD_GOAL,
        smartlinks, smartlinkGoal:NEW_USER_TUTORIAL_SMARTLINK_GOAL,
        completed,
        rewardClaimed:user.newUserTutorialRewardClaimed === true
    };
}

async function ensureNewUserWelcome(userId) {
    let current = await readUserRow(String(userId));
    if (!current.data || current.data.newUserWelcomeEligible !== true) {
        return {eligible:false,claimed:current.data?.newUserWelcomeClaimed === true,user:current.data || null};
    }
    if (current.data.newUserWelcomeClaimed === true) return {eligible:true,claimed:true,user:current.data};

    const release = await acquirePersistentLeaseLock(persistentEventKey('new-user-welcome-lock', String(userId)), 30 * 1000);
    if (!release) return {eligible:true,claimed:false,retry:true,user:current.data};
    try {
        current = await readUserRow(String(userId));
        if (!current.data || current.data.newUserWelcomeEligible !== true) return {eligible:false,claimed:false,user:current.data || null};
        if (current.data.newUserWelcomeClaimed === true) return {eligible:true,claimed:true,user:current.data};

        const payoutId = `new-user-welcome:${String(userId)}`;
        const markerKey = persistentEventKey('new-user-welcome-payout', String(userId));
        let marker = await readPersistentEvent(markerKey);
        if (!marker) {
            const reservation = {
                status:'reserved',payoutId,userId:String(userId),
                preCoins:Number(current.data.coins||0),preOrders:Number(current.data.orders||0),
                targetCoins:Number(current.data.coins||0)+NEW_USER_WELCOME_COINS,
                targetOrders:Number(current.data.orders||0)+NEW_USER_WELCOME_ORDERS,
                createdAt:Date.now()
            };
            const once=await createPersistentEventOnce(markerKey,reservation);
            if (once.error) throw once.error;
            marker=once.value||reservation;
        }
        if (marker.status !== 'committed') {
            current=await readUserRow(String(userId));
            const row=current.data;
            if (!row) throw new Error('Không đọc được user khi phát quà chào mừng.');
            const alreadyApplied=String(row.newUserWelcomePayoutId||'')===payoutId
                || (marker.status==='mutating'
                    && Number(row.coins||0)>=Number(marker.targetCoins||Number.MAX_SAFE_INTEGER)
                    && Number(row.orders||0)>=Number(marker.targetOrders||Number.MAX_SAFE_INTEGER));
            if (!alreadyApplied) {
                marker={...marker,status:'mutating',mutatingAt:Date.now()};
                if (!(await writePersistentEvent(markerKey,marker,4))) throw new Error('Không lưu được marker welcome.');
                const mutation=await atomicWalletMutation(String(userId),{
                    deltaCoins:NEW_USER_WELCOME_COINS,deltaOrders:NEW_USER_WELCOME_ORDERS,
                    setFields:{newUserWelcomeClaimed:true,newUserWelcomeClaimedAt:new Date().toISOString(),newUserWelcomePayoutId:payoutId}
                });
                if (mutation.error) throw mutation.error;
                if (!(await flushUserExtra())) throw new Error('Không flush được welcome state.');
            } else if (row.newUserWelcomeClaimed !== true) {
                await saveUserFields(String(userId),{newUserWelcomeClaimed:true,newUserWelcomeClaimedAt:new Date().toISOString(),newUserWelcomePayoutId:payoutId});
                if (!(await flushUserExtra())) throw new Error('Không phục hồi được welcome claimed state.');
            }
            marker={...marker,status:'committed',committedAt:marker.committedAt||Date.now()};
            if (!(await writePersistentEvent(markerKey,marker,4))) throw new Error('Không commit được welcome marker.');
        }
        if (!marker.transactionLogged) {
            const reasonCoin=`Quà chào mừng user mới | payout=${payoutId} | coin`;
            const reasonOrders=`Quà chào mừng user mới | payout=${payoutId} | orders`;
            const {data:txCoin}=await supabase.from('transactions').select('userId').eq('userId',String(userId)).eq('reason',reasonCoin).limit(1);
            if (!txCoin?.length) await insertRowSafe('transactions',{userId:String(userId),type:'coin',amount:NEW_USER_WELCOME_COINS,reason:reasonCoin});
            const {data:txOrders}=await supabase.from('transactions').select('userId').eq('userId',String(userId)).eq('reason',reasonOrders).limit(1);
            if (!txOrders?.length) await insertRowSafe('transactions',{userId:String(userId),type:'orders',amount:NEW_USER_WELCOME_ORDERS,reason:reasonOrders});
            marker={...marker,transactionLogged:true};
            await writePersistentEvent(markerKey,marker,3);
        }
        const fresh=await readUserRow(String(userId));
        return {eligible:true,claimed:true,user:fresh.data||null};
    } finally { try { await release(); } catch (_) {} }
}

async function maybeCompleteNewUserTutorial(userId, {userLockHeld=false} = {}) {
    let current=await readUserRow(String(userId));
    if (!current.data) return {eligible:false};
    let status=newUserTutorialStatusFromRow(current.data);
    if (!status.eligible || status.rewardClaimed || !status.completed) return status;

    const release=await acquirePersistentLeaseLock(persistentEventKey('new-user-tutorial-lock',String(userId)),30*1000);
    if (!release) return {...status,retry:true};
    try {
        current=await readUserRow(String(userId));
        if (!current.data) return status;
        status=newUserTutorialStatusFromRow(current.data);
        if (!status.eligible || status.rewardClaimed || !status.completed) return status;

        const payoutId=`new-user-tutorial:${String(userId)}`;
        const markerKey=persistentEventKey('new-user-tutorial-payout',String(userId));
        let marker=await readPersistentEvent(markerKey);
        if (!marker) {
            const reservation={status:'reserved',payoutId,userId:String(userId),preSpins:Number(current.data.spins||0),targetSpins:Number(current.data.spins||0)+1,createdAt:Date.now()};
            const once=await createPersistentEventOnce(markerKey,reservation);
            if (once.error) throw once.error;
            marker=once.value||reservation;
        }
        if (marker.status!=='committed') {
            current=await readUserRow(String(userId));
            const row=current.data;
            if (!row) throw new Error('Không đọc được user khi trao thưởng tân thủ.');
            const alreadyApplied=String(row.newUserTutorialPayoutId||'')===payoutId
                || (marker.status==='mutating' && Number(row.spins||0)>=Number(marker.targetSpins||Number.MAX_SAFE_INTEGER));
            if (!alreadyApplied) {
                marker={...marker,status:'mutating',mutatingAt:Date.now()};
                if (!(await writePersistentEvent(markerKey,marker,4))) throw new Error('Không lưu được marker tutorial.');
                const mutationFn=userLockHeld?atomicWalletMutationUnlocked:atomicWalletMutation;
                const mutation=await mutationFn(String(userId),{
                    deltaSpins:1,
                    setFields:{newUserTutorialCompleted:true,newUserTutorialRewardClaimed:true,newUserTutorialRewardClaimedAt:new Date().toISOString(),newUserTutorialPayoutId:payoutId}
                });
                if (mutation.error) throw mutation.error;
                if (!(await flushUserExtra())) throw new Error('Không flush được tutorial state.');
            } else if (row.newUserTutorialRewardClaimed!==true) {
                await saveUserFields(String(userId),{newUserTutorialCompleted:true,newUserTutorialRewardClaimed:true,newUserTutorialRewardClaimedAt:new Date().toISOString(),newUserTutorialPayoutId:payoutId});
                if (!(await flushUserExtra())) throw new Error('Không phục hồi được tutorial claimed state.');
            }
            marker={...marker,status:'committed',committedAt:marker.committedAt||Date.now()};
            if (!(await writePersistentEvent(markerKey,marker,4))) throw new Error('Không commit được tutorial marker.');
        }
        if (!marker.fraudLogged) {
            await recordAntiFraudEvent(String(userId),'task',{rewardEvent:true,coins:0,orders:0,spins:1});
            marker={...marker,fraudLogged:true};
            await writePersistentEvent(markerKey,marker,2);
        }
        const fresh=await readUserRow(String(userId));
        return {...newUserTutorialStatusFromRow(fresh.data||{}),spins:Number(fresh.data?.spins||0),walletUpdatedAt:fresh.data?.walletUpdatedAt||null};
    } finally { try { await release(); } catch (_) {} }
}

async function createMiniAppUserIfMissing(req,userId) {
    const tgUser=telegramUserFromRequest(req);
    if (!tgUser || String(tgUser.id)!==String(userId)) return {data:null,error:new Error('Telegram session không hợp lệ.'),created:false};
    const newUser=buildNewUserRecord(String(userId),[tgUser.first_name,tgUser.last_name].filter(Boolean).join(' ')||'Shipper',null,'vi');
    const inserted=await insertNewUserRecord(newUser);
    if (!inserted.error) return inserted;
    // Hai request mở app đồng thời có thể cùng thấy chưa có row; request thua unique insert chỉ cần đọc lại.
    const reread=await readUserRow(String(userId));
    if (reread.data) return {data:reread.data,error:null,created:false};
    return inserted;
}

app.get('/api/new-user/status/:id', async (req,res) => {
    try {
        const userId=String(req.params.id||'');
        if (!assertTelegramUser(req,userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
        const welcome=await ensureNewUserWelcome(userId);
        const tutorial=await maybeCompleteNewUserTutorial(userId);
        const fresh=await readUserRow(userId);
        if (!fresh.data) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        res.json({success:true,welcome:{eligible:welcome.eligible===true,claimed:fresh.data.newUserWelcomeClaimed===true},tutorial,coins:Number(fresh.data.coins||0),orders:Number(fresh.data.orders||0),spins:Number(fresh.data.spins||0),walletUpdatedAt:fresh.data.walletUpdatedAt||null});
    } catch(e) { console.error('New-user status:',e); res.status(500).json({success:false,error:e.message}); }
});

// API lấy user (kèm level stats)
app.get('/api/user/:id', async (req, res) => {
    const requestedUserId = String(req.params.id || '');
    if (!assertTelegramUser(req, requestedUserId)) return res.status(401).json({error:'Telegram session không hợp lệ.',onboardingRequired:true});
    try {
        let { data, error } = await readUserRow(requestedUserId);
        if (!data) {
            if (error && error.code !== 'PGRST116') {
                console.error('Lỗi lấy user:', error);
                return res.status(500).json({error:'Failed to fetch user data'});
            }
            const created = await createMiniAppUserIfMissing(req, requestedUserId);
            if (created.error || !created.data) {
                console.error(`Không tạo được user Mini App ${requestedUserId}:`, created.error?.message || created.error);
                return res.status(503).json({error:'Không thể tạo tài khoản lúc này.',retry:true});
            }
            data = created.data;
        }

        // Daily source-of-truth: 00:00 Asia/Ho_Chi_Minh, bao gồm counter passive mới.
        if (!isCurrentVietnamDay(data.lastResetDate)) {
            const { error:resetError } = await saveUserFields(requestedUserId, {
                ...dailyResetFields(), walletUpdatedAt:new Date().toISOString()
            });
            if (resetError) return res.status(500).json({error:resetError.message});
            if (!(await flushUserExtra())) return res.status(503).json({error:'Không thể lưu daily reset an toàn lúc này.',retry:true});
            ({data}=await readUserRow(requestedUserId));
        }

        // Quà chào mừng chỉ dành cho row thực sự được tạo với eligible=true từ phiên bản này.
        // GET Mini App là lần mở app đầu tiên; /start chỉ tạo eligibility, không tự phát quà.
        await ensureNewUserWelcome(requestedUserId);
        await maybeCompleteNewUserTutorial(requestedUserId);
        ({data}=await readUserRow(requestedUserId));
        if (!data) return res.status(404).json({error:'User not found'});

        const onboarding = await getOnboardingAccessState(requestedUserId, data);
        if (onboarding.reliable === false) return res.status(503).json({error:'Không đọc được trạng thái onboarding.',retry:true});
        data.onboardingGroupsVerified = onboarding.verified === true;
        data.onboardingGroupsVerifiedAt = onboarding.verifiedAt || null;
        data.onboardingGroupsLegacy = onboarding.legacy === true;

        // Amount milestone cũ trong Supabase không bao giờ override bảng chuẩn trong code; chỉ giữ claimed flag.
        const milestoneClaims = await persistCanonicalMilestoneClaims(requestedUserId, data);
        data.referralMilestones = canonicalReferralMilestones(milestoneClaims);
        data.newUserTutorial = newUserTutorialStatusFromRow(data);
        data.newUserWelcome = {eligible:data.newUserWelcomeEligible===true,claimed:data.newUserWelcomeClaimed===true};

        const groupTaskCampaignClaims = {};
        for (const campaignId of Object.keys(GROUP_TASK_CAMPAIGNS)) {
            groupTaskCampaignClaims[campaignId] = await isGroupTaskCampaignClaimed(requestedUserId, campaignId);
        }
        data.groupTaskClaimed = !!groupTaskCampaignClaims[GROUP_TASK_CAMPAIGN_ID];
        data.groupTaskCampaignId = GROUP_TASK_CAMPAIGN_ID;
        data.groupTaskCampaignClaims = groupTaskCampaignClaims;

        const levelStats = calculateLevelStats(data.truckLevel || 1);
        data.deliveryLimit = DELIVERY_DAILY_LIMIT;
        data.extraDeliveryCount = 0;
        data.extraDeliveryAdsToday = 0;
        res.json({...data,levelStats});
    } catch(e) {
        console.error('Lỗi API lấy user:',e);
        res.status(500).json({error:e.message || 'Failed to fetch user data'});
    }
});

// API cập nhật user. QUAN TRỌNG: các field "ví" (coins/orders/spins/truckLevel/isBanned) được đối chiếu
// qua walletUpdatedAt để KHÔNG cho phép dữ liệu game trên client (vốn chỉ lưu snapshot cục bộ) ghi đè
// mất các thay đổi mà ADMIN vừa thực hiện trực tiếp trên database (đây là nguyên nhân gây lỗi "lệnh admin
// không áp dụng được"). Cách hoạt động: client gửi kèm clientWalletSyncedAt = mốc walletUpdatedAt mà nó
// biết gần nhất. Nếu mốc đó CŨ HƠN mốc hiện tại trong DB (tức admin vừa sửa ví sau khi client đồng bộ lần
// cuối) thì server sẽ BỎ QUA phần ví client gửi lên, giữ nguyên giá trị admin đã đặt, và trả lại giá trị
// mới nhất để client tự cập nhật lại local state.
// Toàn bộ field có thể bị ADMIN thay đổi trực tiếp qua lệnh bot (congcoin, trucoin, addspin, adddonhang,
// setlevel, ban/unban, resetdaily, reset, resetall...) được đối chiếu qua walletUpdatedAt để KHÔNG cho
// phép dữ liệu game trên client (vốn chỉ lưu snapshot cục bộ, có thể cũ) ghi đè mất thay đổi của admin.
// Lấy trực tiếp từ fullResetFields() để danh sách này LUÔN khớp với những gì các lệnh reset thực sự đổi,
// tránh trường hợp thêm field mới vào fullResetFields() mà quên thêm vào đây.
// FIX LỖI "XEM QC TĂNG TỐC X2 THÀNH CÔNG NHƯNG THỜI GIAN KHÔNG GIẢM": 'speedUpUsed' trước đây KHÔNG nằm
// trong danh sách WALLET_FIELDS (vì fullResetFields() không có field này), nên khi walletOverridden=true
// (server phát hiện dữ liệu ví trên DB mới hơn mốc client đã đồng bộ), 'lastProducedAt'/'productionInterval'
// bị loại khỏi bản lưu (đúng, để không mất thay đổi mới hơn) NHƯNG 'speedUpUsed' vẫn được lưu bình thường
// -> kết quả: speedUpUsed=true được ghi nhận (đã dùng X2) trong khi lastProducedAt/productionInterval bị
// hoàn tác về giá trị cũ (thời gian KHÔNG giảm) -> user thấy "xem QC xong nhưng thời gian không đổi" và
// còn bị khoá không cho dùng X2 lần nữa cho mẻ đó. Thêm 'speedUpUsed' vào WALLET_FIELDS để nó LUÔN được
// hoàn tác/giữ nguyên ĐỒNG BỘ cùng lastProducedAt/productionInterval trong cùng 1 lần ghi đè, đảm bảo
// trạng thái X2 và thời gian sản xuất không bao giờ bị lệch nhau.
const WALLET_FIELDS = [...new Set([...Object.keys(fullResetFields()), 'isBanned', 'speedUpUsed', 'maxProducts', 'productionAmount', 'dailyTasks', 'allTasksClaimed'])];
app.post('/api/user/:id', async (req, res) => {
    const requestedUserId = String(req.params.id || '');
    if (!assertTelegramUser(req, requestedUserId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    const releaseUserStateWrite = await acquireUserStateWriteLock(requestedUserId);
    try {
        const userId = req.params.id;
        const { clientWalletSyncedAt, ...body } = req.body;
        let updateData = { ...body };

        // SECURITY: referral relationship/counters are server-owned and immutable from the client.
        // This endpoint is a compatibility sync route for legacy UI state only.
        [
            'referrerId', 'referrerCounted', 'invitedCount', 'validInvites',
            'weeklyValidInvites', 'lifetimeAdsWatched', 'lifetimeSmartlinks',
            'adsToday', 'smartlinksToday', 'smartlinkCount', 'deliveryCount',
            'deliveryCountLifetime', 'chestOpensTotal', 'chestOpensToday',
            'referralMilestones', 'dailyValidInvites',
            'bonusAdsToday','bonusAdNextAllowedAt','lastBonusAdToken','rewardedAdsToday','extraDeliveryAdsToday','extraDeliveryCount','withdrawRemain','spinAdCount','groupTaskClaimed',
            'lastSmartlinkTime','lastSmartlinkAttemptId',
            'quizDate', 'quizFreeUsed', 'quizAdUnlocked', 'quizUsedIds',
            'dailyTasks', 'allTasksClaimed', 'lastResetDate',
            'serverTaskClaims', 'dailyActionFlags', 'loginStreakState', 'groupTaskClaimed', 'lastDailyTaskPayoutId', 'lastDailyTaskAllPayoutId',
            'groupTaskCampaignClaims', 'groupTaskCampaignId',
            'onboardingGroupsVerified', 'onboardingGroupsVerifiedAt', 'onboardingGroupsLegacy',
            'newUserWelcomeEligible','newUserWelcomeClaimed','newUserWelcomeClaimedAt','newUserWelcomePayoutId',
            'newUserTutorialEligible','newUserTutorialCompleted','newUserTutorialRewardClaimed','newUserTutorialRewardClaimedAt','newUserTutorialPayoutId','newUserTutorialBaseAds','newUserTutorialBaseSmartlinks',
            'passiveAdsToday','passiveAdsDayKey','passiveAdNextAllowedAt','lastManualRewardedCompletedAt','lastPassiveAdToken',
            'serverReferralMilestones','lastReferralMilestonePayoutId','lastWeeklyPayoutId',
            'job_mail_banned'
        ].forEach(f => { delete updateData[f]; });

        // Handle referralMilestones as JSON string
        if (updateData.referralMilestones) {
            updateData.referralMilestones = JSON.stringify(updateData.referralMilestones);
        }

        let { data: current, error: currentError } = await readUserRow(userId);
        if (!current) {
            // Mini App mở trước /start: tạo account server-side với cùng default như /start và đánh dấu eligible đúng một lần.
            const tgUser = telegramUserFromRequest(req);
            const seed = buildNewUserRecord(userId,
                [tgUser?.first_name, tgUser?.last_name].filter(Boolean).join(' ') || body.name || 'Shipper',
                null,
                body.language || 'vi');
            const created = await insertNewUserRecord(seed);
            if (created.error) {
                const reread = await readUserRow(userId);
                current = reread.data;
                if (!current) {
                    console.error(`Không tạo được user ${userId}:`, created.error.message || currentError?.message);
                    return res.status(503).json({success:false,error:'Không thể tạo tài khoản lúc này.',retry:true});
                }
            } else current = created.data;
            await ensureNewUserWelcome(userId);
            ({data:current} = await readUserRow(userId));
            if (!current) return res.status(404).json({success:false,error:'User not found'});
        }
        if (current.isBanned) {
            return res.status(403).json({ success: false, error: "Tài khoản đã bị khóa.", isBanned: true });
        }

        const dbWalletTime = current.walletUpdatedAt ? new Date(current.walletUpdatedAt).getTime() : 0;
        const clientTime = clientWalletSyncedAt ? new Date(clientWalletSyncedAt).getTime() : 0;
        let walletOverridden = false;

        let saveError = null;
        if (dbWalletTime > clientTime) {
            // Server đã có wallet version mới hơn snapshot client -> tuyệt đối không nhận giá trị ví cũ.
            WALLET_FIELDS.forEach(f => { delete updateData[f]; });
            walletOverridden = true;
            ({ error:saveError } = await saveUserFields(userId, updateData));
        } else {
            // Client đang nhìn đúng wallet version tại thời điểm READ, nhưng một instance khác vẫn có thể
            // credit reward ngay sau dòng này. Vì vậy UPDATE ví phải CAS theo walletUpdatedAt + coins/orders/spins.
            // Nếu CAS trượt, chỉ lưu các field không thuộc wallet và trả fresh wallet về client.
            updateData.walletUpdatedAt = new Date().toISOString();
            const cas = await saveUserFieldsWithWalletCas(userId, updateData, current);
            saveError = cas.error || null;
            if (!saveError && cas.conflict) {
                WALLET_FIELDS.forEach(f => { delete updateData[f]; });
                delete updateData.walletUpdatedAt;
                walletOverridden = true;
                ({ error:saveError } = await saveUserFields(userId, updateData));
            }
        }

        if (saveError) {
            console.error(`Lỗi cập nhật user ${userId}:`, saveError.message || saveError);
            return res.status(500).json({ success: false, error: saveError.message });
        }

        if (walletOverridden) {
            // Trả về giá trị mới nhất từ DB cho TOÀN BỘ field được bảo vệ để client tự đồng bộ lại, tránh mất thay đổi của admin
            const { data: fresh } = await readUserRow(userId);
            if (fresh && fresh.referralMilestones && typeof fresh.referralMilestones === 'string') {
                try { fresh.referralMilestones = JSON.parse(fresh.referralMilestones); } catch (_) { fresh.referralMilestones = []; }
            }
            const levelStats = calculateLevelStats(fresh?.truckLevel || 1);
            return res.json({ success: true, walletOverridden: true, wallet: fresh, levelStats });
        }

        // Lấy dữ liệu cập nhật mới nhất để trả về level stats
        const { data: updated } = await supabase.from('users').select('truckLevel').eq('id', userId).single();
        const levelStats = calculateLevelStats(updated?.truckLevel || 1);
        
        res.json({ success: true, walletOverridden: false, walletUpdatedAt: updateData.walletUpdatedAt, levelStats });
    } catch (e) {
        console.error("Lỗi API cập nhật user:", e);
        res.status(500).json({ success: false, error: e.message });
    } finally {
        releaseUserStateWrite();
    }
});

// ==================== JOB MAIL API ====================
function chunkArray(items, size = 500) {
    const out = [];
    for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
    return out;
}

app.post('/api/job-mail/submit', async (req, res) => {
    const userId = String(req.body?.userId || '');
    if (!assertTelegramUser(req, userId)) return res.status(401).json({ success:false, error:'Telegram session không hợp lệ.' });
    if (!userId) return res.status(400).json({ success:false, error:'Thiếu userId.' });
    try {
        const verifiedTgUser = telegramUserFromRequest(req);
        const { data:user, error:userError } = await readUserRow(userId);
        if (userError || !user) return res.status(404).json({ success:false, error:'Không tìm thấy user.' });
        if (user.isBanned) return res.status(403).json({ success:false, isBanned:true, error:'Tài khoản đã bị khóa.' });
        if (user.job_mail_banned === true) return res.status(403).json({ success:false, jobMailBanned:true, error:'JOB MAIL đã bị khóa cho tài khoản này.' });

        // Source of truth: manual lock persist Supabase + giờ thực tế Asia/Ho_Chi_Minh. Không dùng timer/giờ browser.
        const availability = await getJobMailAvailability();
        if (availability.jobMailManualLocked) {
            return res.status(423).json({
                success:false,
                jobMailClosed:true,
                ...jobMailAvailabilityPayload(availability),
                error:'❌ JOB MAIL hiện đang được Admin tạm khóa.'
            });
        }
        if (!availability.jobMailScheduleOpen) {
            return res.status(423).json({
                success:false,
                jobMailClosed:true,
                ...jobMailAvailabilityPayload(availability),
                error:'❌ JOB MAIL hiện đã đóng. Thời gian nhận mail từ 06:00 đến 21:00.'
            });
        }

        const rawInput = Array.isArray(req.body?.emails) ? req.body.emails : String(req.body?.emails || '').split(/\r?\n/);
        const nonEmpty = rawInput.map(v => String(v || '').trim()).filter(Boolean);
        if (nonEmpty.length < JOB_MAIL_MIN_BATCH) {
            return res.status(400).json({
                success:false,
                jobMailMinBatch:JOB_MAIL_MIN_BATCH,
                error:`❌ Mỗi lần gửi cần ít nhất ${JOB_MAIL_MIN_BATCH} Gmail.`
            });
        }

        let invalid = 0, duplicateBatch = 0;
        const unique = new Map();
        for (const original of nonEmpty) {
            const normalized = normalizeJobMailEmail(original);
            if (!JOB_MAIL_EMAIL_REGEX.test(original)) { invalid++; continue; }
            if (unique.has(normalized)) { duplicateBatch++; continue; }
            unique.set(normalized, original);
        }

        const sourceIp = requestIp(req);
        const username = String(verifiedTgUser?.username || '').replace(/^@/,'').slice(0,100) || null;
        const candidates = [...unique.entries()].map(([emailNormalized,emailOriginal]) => ({
            email_normalized:emailNormalized,
            email_original:emailOriginal,
            user_id:userId,
            username,
            status:'pending',
            reject_reason:null,
            submitted_at:new Date().toISOString(),
            reviewed_at:null,
            reviewed_by:null,
            reward_orders:JOB_MAIL_REWARD_ORDERS,
            reward_credited:false,
            source_ip:sourceIp,
            created_at:new Date().toISOString(),
            updated_at:new Date().toISOString()
        }));

        const inserted = [];
        for (const batch of chunkArray(candidates, 500)) {
            if (!batch.length) continue;
            const { data, error } = await jobMailDb().from('job_mails')
                .upsert(batch, { onConflict:'email_normalized', ignoreDuplicates:true })
                .select('id,email_normalized,email_original,status');
            if (error) throw error;
            inserted.push(...(data || []));
        }
        const duplicateSystem = Math.max(0, candidates.length - inserted.length);
        const stats = await getJobMailUserStats(userId);
        return res.json({
            success:true,
            totalInput:nonEmpty.length,
            accepted:inserted.length,
            valid:inserted.length,
            duplicateBatch,
            duplicateSystem,
            invalid,
            pendingAdded:inserted.length,
            stats,
            ...jobMailAvailabilityPayload(availability)
        });
    } catch (e) {
        console.error('JOB MAIL submit:',e);
        if (jobMailDbUnavailable(e)) return res.status(503).json({ success:false, migrationRequired:String(e?.code || '') !== 'JOB_MAIL_SERVICE_ROLE_MISSING', serviceRoleRequired:String(e?.code || '') === 'JOB_MAIL_SERVICE_ROLE_MISSING', error:jobMailSetupMessage(e).replace(/^❌\s*/, '') });
        return res.status(500).json({ success:false, error:'Không thể gửi JOB MAIL lúc này.' });
    }
});

app.get('/api/job-mail/me/:userId', async (req, res) => {
    const userId = String(req.params.userId || '');
    if (!assertTelegramUser(req, userId)) return res.status(401).json({ success:false, error:'Telegram session không hợp lệ.' });
    try {
        const { data:user, error:userError } = await readUserRow(userId);
        if (userError || !user) return res.status(404).json({ success:false, error:'Không tìm thấy user.' });
        const page = Math.max(1, Math.trunc(Number(req.query.page || 1)));
        const offset = (page - 1) * JOB_MAIL_HISTORY_PAGE_SIZE;
        const [stats, historyResult, availability] = await Promise.all([
            getJobMailUserStats(userId),
            jobMailDb().from('job_mails')
                .select('id,email_original,status,reject_reason,submitted_at,reviewed_at,reward_orders,reward_credited', { count:'exact' })
                .eq('user_id', userId).order('submitted_at',{ascending:false})
                .range(offset, offset + JOB_MAIL_HISTORY_PAGE_SIZE - 1),
            getJobMailAvailability()
        ]);
        if (historyResult.error) throw historyResult.error;
        const totalPages = Math.max(1, Math.ceil(Number(historyResult.count || 0) / JOB_MAIL_HISTORY_PAGE_SIZE));
        return res.json({
            success:true,
            jobMailBanned:user.job_mail_banned === true,
            stats,
            history:historyResult.data || [],
            page:Math.min(page,totalPages),
            totalPages,
            pageSize:JOB_MAIL_HISTORY_PAGE_SIZE,
            ...jobMailAvailabilityPayload(availability)
        });
    } catch (e) {
        console.error('JOB MAIL me:',e);
        if (jobMailDbUnavailable(e)) return res.status(503).json({ success:false, migrationRequired:String(e?.code || '') !== 'JOB_MAIL_SERVICE_ROLE_MISSING', serviceRoleRequired:String(e?.code || '') === 'JOB_MAIL_SERVICE_ROLE_MISSING', error:jobMailSetupMessage(e).replace(/^❌\s*/, '') });
        return res.status(500).json({ success:false, error:'Không tải được JOB MAIL.' });
    }
});

// ==================== SMARTLINK ====================
// Each valid SmartLink completion = +25 Coin +25 Orders.
// Server owns attemptId + startedAt; client timestamps are never trusted for reward eligibility.
const smartlinkProcessing = new Set();
const SMARTLINK_DAILY_LIMIT = 20;
const SMARTLINK_REWARD_COINS = 25;
const SMARTLINK_REWARD_ORDERS = 25;
const SMARTLINK_MIN_ELAPSED_MS = 5000;
const SMARTLINK_COOLDOWN_MS = 30 * 1000;
const SMARTLINK_ATTEMPT_TTL_MS = 15 * 60 * 1000;
const SMARTLINK_MONETAG_POOL = Object.freeze(["https://omg10.com/4/10406572", "https://omg10.com/4/10406571", "https://omg10.com/4/10406596", "https://omg10.com/4/10406591", "https://omg10.com/4/10406568", "https://omg10.com/4/10406576", "https://omg10.com/4/10406590", "https://omg10.com/4/10406566", "https://omg10.com/4/10406574", "https://omg10.com/4/10406589", "https://omg10.com/4/10406570", "https://omg10.com/4/10406586", "https://omg10.com/4/10406538", "https://omg10.com/4/10406567", "https://omg10.com/4/10406588", "https://omg10.com/4/10406587", "https://omg10.com/4/10406592", "https://omg10.com/4/10406575", "https://omg10.com/4/10406598", "https://omg10.com/4/10406577"]);
function isAllowedSmartlinkUrl(value) {
    try {
        const url = new URL(String(value || ''));
        if (url.protocol !== 'https:') return false;
        const host = url.hostname.toLowerCase();
        return host === 'omg10.com' || host.endsWith('.omg10.com');
    } catch (_) { return false; }
}
function smartlinkSelectionForSuccessNumber(value) {
    const successNumber = Math.max(1, Math.trunc(Number(value || 1)));
    const link = SMARTLINK_MONETAG_POOL[(successNumber - 1) % SMARTLINK_MONETAG_POOL.length];
    return { provider:'monetag', link, successNumber };
}
function smartlinkAttemptKey(attemptId) {
    return persistentEventKey('smartlink-attempt', String(attemptId || ''));
}

app.post('/api/smartlink/start', async (req, res) => {
    const userId = String(req.body?.userId || '');
    if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res)) return;
    if (!userId) return res.status(400).json({success:false,error:'Thiếu userId.'});
    try {
        const user = await loadCurrentDailyUser(userId);
        if (!user) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        if (user.isBanned) return res.status(403).json({success:false,isBanned:true,error:'Tài khoản đã bị khóa.'});
        const count = Math.max(0, Number(user.smartlinksToday || user.smartlinkCount || 0));
        if (count >= SMARTLINK_DAILY_LIMIT) {
            return res.status(429).json({success:false,limitReached:true,smartlinksToday:count,error:'Đã hết 20 lượt SmartLink hôm nay.'});
        }
        const nextAllowedAt = Math.max(0, Number(user.lastSmartlinkTime || 0)) + SMARTLINK_COOLDOWN_MS;
        if (Date.now() < nextAllowedAt) {
            return res.status(429).json({
                success:false,cooldown:true,
                retryAfterMs:Math.max(1,nextAllowedAt-Date.now()),
                nextAllowedAt,
                smartlinksToday:count,
                error:'SmartLink đang trong thời gian chờ 30 giây.'
            });
        }
        // Provider/link is server-authoritative and advances ONLY from lifetime successful SmartLinks.
        const selection = smartlinkSelectionForSuccessNumber(Number(user.lifetimeSmartlinks || 0) + 1);
        if (!isAllowedSmartlinkUrl(selection.link)) {
            return res.status(500).json({success:false,retry:true,error:'Cấu hình SmartLink server không hợp lệ.'});
        }
        const attemptId = crypto.randomBytes(18).toString('hex');
        const startedAt = Date.now();
        const attempt = {
            userId, link:selection.link, provider:selection.provider, successNumber:selection.successNumber,
            status:'started', used:false, startedAt,
            expiresAt:startedAt + SMARTLINK_ATTEMPT_TTL_MS,
            dayKey:vietnamDayKey()
        };
        const saved = await writePersistentEvent(smartlinkAttemptKey(attemptId), attempt, 3);
        if (!saved) return res.status(503).json({success:false,retry:true,error:'Chưa tạo được phiên SmartLink. Vui lòng thử lại.'});
        return res.json({
            success:true,attemptId,startedAt,expiresAt:attempt.expiresAt,minElapsedMs:SMARTLINK_MIN_ELAPSED_MS,
            provider:selection.provider,link:selection.link
        });
    } catch (e) {
        console.error('Lỗi bắt đầu SmartLink:', e);
        return res.status(500).json({success:false,retry:true,error:e.message});
    }
});

app.post('/api/smartlink/complete', async (req, res) => {
    const userId = String(req.body?.userId || '');
    if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res)) return;
    const attemptId = String(req.body?.attemptId || '');
    if (!userId) return res.status(400).json({success:false,error:'Thiếu userId.'});
    if (!attemptId) return res.status(400).json({success:false,error:'Thiếu SmartLink attemptId.'});
    if (smartlinkProcessing.has(userId)) return res.status(409).json({success:false,retry:true,error:'Lượt SmartLink đang được xử lý.'});
    smartlinkProcessing.add(userId);
    const releaseUserStateWrite = await acquireUserStateWriteLock(userId);
    let releasePersistentSmartlinkLock = null;
    try {
        releasePersistentSmartlinkLock = await acquirePersistentLeaseLock(
            persistentEventKey('smartlink-user-lock', userId),
            2 * 60 * 1000
        );
        if (!releasePersistentSmartlinkLock) {
            return res.status(409).json({success:false,retry:true,error:'Lượt SmartLink đang được xử lý trên máy chủ khác.'});
        }
        const legacyResultKey = persistentEventKey('smartlink', `${userId}:${attemptId}`);
        const legacyResult = await readPersistentEvent(legacyResultKey);
        if (legacyResult?.success) return res.json({...legacyResult,idempotent:true});

        const attemptKey = smartlinkAttemptKey(attemptId);
        let attempt = await readPersistentEvent(attemptKey);
        if (!attempt || String(attempt.userId || '') !== userId) {
            return res.status(400).json({success:false,invalidAttempt:true,error:'Không tìm thấy phiên SmartLink hợp lệ. Vui lòng thử lại.'});
        }
        if (attempt.status === 'completed' && attempt.result?.success) {
            return res.json({...attempt.result,idempotent:true});
        }
        if (attempt.expiresAt && Date.now() >= Number(attempt.expiresAt)) {
            return res.status(410).json({success:false,attemptExpired:true,error:'Phiên SmartLink đã hết hạn. Vui lòng thử lại.'});
        }
        const elapsed = Date.now() - Number(attempt.startedAt || 0);
        if (!Number.isFinite(elapsed) || elapsed < SMARTLINK_MIN_ELAPSED_MS) {
            const language = await getStoredUserLanguage(userId);
            return res.status(425).json({
                success:false,tooEarly:true,elapsed,minElapsedMs:SMARTLINK_MIN_ELAPSED_MS,
                error:language === 'en'
                    ? 'You must wait at least 5 seconds. Please try again!!'
                    : 'Cần Đợi Tối Thiểu 5s.Vui Lòng Thử Lại!!'
            });
        }

        let user = await loadCurrentDailyUser(userId);
        if (!user) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        if (user.isBanned) return res.status(403).json({success:false,isBanned:true,error:'Tài khoản đã bị khóa.'});
        if (attempt.status === 'started') {
            const expectedSelection = smartlinkSelectionForSuccessNumber(Number(user.lifetimeSmartlinks || 0) + 1);
            if (Number(attempt.successNumber || 0) !== expectedSelection.successNumber) {
                return res.status(409).json({success:false,retry:true,staleAttempt:true,error:'Phiên SmartLink đã cũ. Vui lòng mở lại SmartLink từ ứng dụng.'});
            }
            if (String(attempt.provider || '') !== expectedSelection.provider || String(attempt.link || '') !== expectedSelection.link) {
                return res.status(400).json({success:false,invalidAttempt:true,error:'Provider SmartLink không khớp với phiên server đã tạo.'});
            }
        }
        const fraudGate = await antiFraudRewardGate(userId);
        if (!fraudGate.allowed) return res.status(fraudGate.status).json({success:false,...fraudGate,verificationRequired:true});

        const finishAttempt = async (freshUser, recovered = false) => {
            const response = {
                success:true,
                rewardCoins:SMARTLINK_REWARD_COINS,rewardOrders:SMARTLINK_REWARD_ORDERS,
                smartlinkCount:Number(freshUser.smartlinkCount || 0),
                smartlinksToday:Number(freshUser.smartlinksToday || 0),
                lifetimeSmartlinks:Number(freshUser.lifetimeSmartlinks || 0),
                coins:Number(freshUser.coins || 0),orders:Number(freshUser.orders || 0),spins:Number(freshUser.spins || 0),
                walletUpdatedAt:freshUser.walletUpdatedAt || null,
                lastSmartlinkTime:Number(freshUser.lastSmartlinkTime || Date.now()),
                provider:String(attempt.provider || ''),link:String(attempt.link || ''),
                elapsed:Date.now()-Number(attempt.startedAt || Date.now())
            };
            const completedAttempt = {...attempt,status:'completed',used:true,completedAt:Date.now(),result:response};
            const savedAttempt = await writePersistentEvent(attemptKey, completedAttempt, 4);
            const savedLegacy = await writePersistentEvent(legacyResultKey,{...response,createdAt:Date.now()},3);
            if (!savedAttempt && !savedLegacy) {
                return {ok:false,response:null};
            }
            attempt = completedAttempt;
            if (!recovered) {
                await recordAntiFraudEvent(userId,'smartlink',{
                    rewardEvent:true,coins:SMARTLINK_REWARD_COINS,orders:SMARTLINK_REWARD_ORDERS,
                    ip:requestIp(req),sessionId:String(req.body?.sessionId || ''),attemptId
                });
                logTransaction(userId,'coin',SMARTLINK_REWARD_COINS,'Hoàn thành 1 SmartLink');
                logTransaction(userId,'orders',SMARTLINK_REWARD_ORDERS,'Hoàn thành 1 SmartLink');
                try { await tryFinalizeReferral(userId); } catch (_) {}
            }
            let tutorial=null;
            try { tutorial=await maybeCompleteNewUserTutorial(userId,{userLockHeld:true}); } catch (e) { console.error('Tutorial after SmartLink:',e.message); }
            const tutorialFresh=await readUserRow(userId);
            if (tutorialFresh.data) {
                response.coins=Number(tutorialFresh.data.coins||response.coins||0);
                response.orders=Number(tutorialFresh.data.orders||response.orders||0);
                response.spins=Number(tutorialFresh.data.spins||response.spins||0);
                response.walletUpdatedAt=tutorialFresh.data.walletUpdatedAt||response.walletUpdatedAt;
            }
            response.tutorial=tutorial;
            const risk = await getAntiFraudState(userId);
            return {ok:true,response:{...response,riskScore:risk.stats.score,...(recovered?{recovered:true}: {})}};
        };

        // Recovery after a crash between wallet commit and completed marker.
        if (attempt.status === 'processing' && attempt.claim) {
            const c = attempt.claim;
            const markerMatches = String(user.lastSmartlinkAttemptId || '') === attemptId;
            // coins+orders are updated in the same Postgres UPDATE. If those wallet targets are already
            // reached after a crash, NEVER add +25/+25 again; repair only the counters/marker below.
            const walletTargetsReached = Number(user.coins || 0) >= Number(c.targetCoins || 0)
                && Number(user.orders || 0) >= Number(c.targetOrders || 0);
            if (markerMatches || walletTargetsReached) {
                const repair = await atomicWalletMutationUnlocked(userId, {
                    setFields:{
                        smartlinkCount:Math.max(Number(user.smartlinkCount || 0),Number(c.targetSmartlinkCount || 0)),
                        smartlinksToday:Math.max(Number(user.smartlinksToday || 0),Number(c.targetSmartlinksToday || 0)),
                        lifetimeSmartlinks:Math.max(Number(user.lifetimeSmartlinks || 0),Number(c.targetLifetimeSmartlinks || 0)),
                        lastSmartlinkTime:Number(c.completedAt || Date.now()),
                        lastSmartlinkAttemptId:attemptId,
                        lastResetDate:vietnamDayKey()
                    }
                });
                if (repair.error) return res.status(409).json({success:false,retry:true,error:repair.error.message});
                const flushed = await flushUserExtra();
                if (!flushed) return res.status(503).json({success:false,retry:true,error:'SmartLink đã được ghi nhận nhưng trạng thái đang đồng bộ. Vui lòng thử lại.'});
                const recovered = await readUserRow(userId);
                if (!recovered.data) return res.status(503).json({success:false,retry:true,error:'Chưa đọc lại được trạng thái SmartLink.'});
                const finished = await finishAttempt(recovered.data, true);
                if (!finished.ok) return res.status(503).json({success:false,retry:true,error:'SmartLink đã hoàn tất nhưng marker đang đồng bộ. Vui lòng thử lại.'});
                return res.json({...finished.response,idempotent:true});
            }
            // Wallet target chưa commit: giữ chính claim này và thử mutation ở dưới, không tạo target mới.
        }

        const currentCount = Math.max(0,Number(user.smartlinkCount || 0));
        const todayCount = Math.max(0,Number(user.smartlinksToday || 0));
        if (todayCount >= SMARTLINK_DAILY_LIMIT || currentCount >= SMARTLINK_DAILY_LIMIT) {
            return res.status(429).json({success:false,limitReached:true,smartlinkCount:currentCount,smartlinksToday:todayCount,error:'Đã hết 20 lượt SmartLink hôm nay.'});
        }

        let claim = attempt.claim;
        if (!claim || attempt.status !== 'processing') {
            claim = {
                status:'processing',reservedAt:Date.now(),completedAt:Date.now(),
                preCoins:Number(user.coins || 0),preOrders:Number(user.orders || 0),
                targetCoins:Number(user.coins || 0)+SMARTLINK_REWARD_COINS,
                targetOrders:Number(user.orders || 0)+SMARTLINK_REWARD_ORDERS,
                targetSmartlinkCount:currentCount+1,
                targetSmartlinksToday:todayCount+1,
                targetLifetimeSmartlinks:Math.max(0,Number(user.lifetimeSmartlinks || 0))+1
            };
            attempt = {...attempt,status:'processing',claim};
            const reserved = await writePersistentEvent(attemptKey, attempt, 4);
            if (!reserved) return res.status(503).json({success:false,retry:true,error:'Chưa giữ được phiên SmartLink. Vui lòng thử lại.'});
        }

        const mutation = await atomicWalletMutationUnlocked(userId,{
            deltaCoins:SMARTLINK_REWARD_COINS,
            deltaOrders:SMARTLINK_REWARD_ORDERS,
            setFields:{
                smartlinkCount:Number(claim.targetSmartlinkCount),
                smartlinksToday:Number(claim.targetSmartlinksToday),
                lifetimeSmartlinks:Number(claim.targetLifetimeSmartlinks),
                lastSmartlinkTime:Number(claim.completedAt || Date.now()),
                lastSmartlinkAttemptId:attemptId,
                lastResetDate:vietnamDayKey()
            }
        });
        if (mutation.error) return res.status(409).json({success:false,retry:true,error:mutation.error.message});

        const flushed = await flushUserExtra();
        if (!flushed) return res.status(503).json({success:false,retry:true,error:'SmartLink đã được ghi nhận nhưng trạng thái đang đồng bộ. Vui lòng thử lại.'});
        let fresh = await readUserRow(userId);
        if (!fresh.data) return res.status(503).json({success:false,retry:true,error:'Chưa đọc lại được trạng thái SmartLink.'});

        const walletCommitted = Number(fresh.data.coins || 0) >= Number(claim.targetCoins)
            && Number(fresh.data.orders || 0) >= Number(claim.targetOrders);
        if (!walletCommitted) {
            return res.status(503).json({success:false,retry:true,error:'Phần thưởng SmartLink chưa commit hoàn toàn. Vui lòng thử lại.'});
        }
        let stateCommitted = String(fresh.data.lastSmartlinkAttemptId || '') === attemptId
            && Number(fresh.data.smartlinkCount || 0) >= Number(claim.targetSmartlinkCount)
            && Number(fresh.data.smartlinksToday || 0) >= Number(claim.targetSmartlinksToday)
            && Number(fresh.data.lifetimeSmartlinks || 0) >= Number(claim.targetLifetimeSmartlinks);
        if (!stateCommitted) {
            const repair = await atomicWalletMutationUnlocked(userId,{
                setFields:{
                    smartlinkCount:Number(claim.targetSmartlinkCount),
                    smartlinksToday:Number(claim.targetSmartlinksToday),
                    lifetimeSmartlinks:Number(claim.targetLifetimeSmartlinks),
                    lastSmartlinkTime:Number(claim.completedAt || Date.now()),
                    lastSmartlinkAttemptId:attemptId,
                    lastResetDate:vietnamDayKey()
                }
            });
            if (repair.error) return res.status(409).json({success:false,retry:true,error:repair.error.message});
            if (!(await flushUserExtra())) return res.status(503).json({success:false,retry:true,error:'SmartLink đang đồng bộ trạng thái. Vui lòng thử lại.'});
            fresh = await readUserRow(userId);
            stateCommitted = !!fresh.data && String(fresh.data.lastSmartlinkAttemptId || '') === attemptId
                && Number(fresh.data.smartlinkCount || 0) >= Number(claim.targetSmartlinkCount)
                && Number(fresh.data.smartlinksToday || 0) >= Number(claim.targetSmartlinksToday)
                && Number(fresh.data.lifetimeSmartlinks || 0) >= Number(claim.targetLifetimeSmartlinks);
        }
        if (!stateCommitted) return res.status(503).json({success:false,retry:true,error:'SmartLink chưa commit đầy đủ. Vui lòng thử lại.'});

        const finished = await finishAttempt(fresh.data, false);
        if (!finished.ok) return res.status(503).json({success:false,retry:true,error:'SmartLink đã commit nhưng marker đang đồng bộ. Vui lòng thử lại.'});
        return res.json(finished.response);
    } catch(e) {
        console.error('Lỗi hoàn tất SmartLink:',e);
        return res.status(500).json({success:false,retry:true,error:e.message});
    } finally {
        if (releasePersistentSmartlinkLock) {
            try { await releasePersistentSmartlinkLock(); } catch (_) {}
        }
        releaseUserStateWrite();
        smartlinkProcessing.delete(userId);
    }
});

// ==================== QUIZ: SERVER CẤP LƯỢT, RELOAD KHÔNG THỂ NHẬN LẠI ====================
const QUIZ_DAILY_LIMIT = 5;
const QUIZ_AD_LIMIT = 4;
const quizProcessing = new Set();
async function loadCurrentDailyUser(userId) {
    let { data: user } = await readUserRow(userId);
    if (!user) return null;
    if (!isCurrentVietnamDay(user.lastResetDate)) {
        // Chỉ sang ngày mới thật sự mới reset toàn bộ nhiệm vụ/QC/SmartLink/giao hàng.
        const saved = await saveUserFields(userId, { ...dailyResetFields(), walletUpdatedAt:new Date().toISOString() });
        if (saved.error) throw saved.error;
        if (!(await flushUserExtra())) throw new Error('Không thể lưu daily reset an toàn lúc này.');
        ({ data:user } = await readUserRow(userId));
    } else if (user.quizDate !== vietnamDayKey()) {
        // Nếu riêng dữ liệu quiz cũ/thiếu thì chỉ reset quiz, tuyệt đối không xóa tiến độ khác trong ngày.
        const saved = await saveUserFields(userId, {
            quizDate:vietnamDayKey(), quizFreeUsed:false, quizAdUnlocked:0, quizUsedIds:[]
        });
        if (saved.error) throw saved.error;
        if (!(await flushUserExtra())) throw new Error('Không thể lưu trạng thái Quiz an toàn lúc này.');
        ({ data:user } = await readUserRow(userId));
    }
    return user;
}
function quizState(user) {
    const quizFreeUsed = !!user?.quizFreeUsed;
    const quizAdUnlocked = Math.min(QUIZ_AD_LIMIT, Math.max(0, Number(user?.quizAdUnlocked || 0)));
    const slotsUsed = (quizFreeUsed ? 1 : 0) + quizAdUnlocked;
    return {
        quizDate: vietnamDayKey(), quizFreeUsed, quizAdUnlocked,
        quizUsedIds: Array.isArray(user?.quizUsedIds) ? user.quizUsedIds.slice(0, QUIZ_DAILY_LIMIT) : [],
        slotsUsed, remaining: Math.max(0, QUIZ_DAILY_LIMIT - slotsUsed)
    };
}
app.get('/api/quiz/status/:id', async (req, res) => {
    const userId = String(req.params.id || '');
    if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    try {
        const user = await loadCurrentDailyUser(userId);
        if (!user) return res.status(404).json({ success:false, error:'Không tìm thấy user.' });
        res.json({ success:true, ...quizState(user) });
    } catch (e) {
        console.error('Lỗi lấy trạng thái câu hỏi:', e);
        res.status(500).json({ success:false, error:e.message });
    }
});
app.post('/api/quiz/claim-slot', async (req, res) => {
    const userId = String(req.body?.userId || '');
    const kind = req.body?.kind === 'ad' ? 'ad' : 'free';
    if (!userId) return res.status(400).json({ success:false, error:'Thiếu userId.' });
    if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if (quizProcessing.has(userId)) return res.status(409).json({ success:false, retry:true, error:'Đang xử lý lượt câu hỏi.' });
    quizProcessing.add(userId);
    try {
        const user = await loadCurrentDailyUser(userId);
        if (!user) return res.status(404).json({ success:false, error:'Không tìm thấy user.' });
        const state = quizState(user);
        if (state.slotsUsed >= QUIZ_DAILY_LIMIT) {
            return res.status(429).json({ success:false, limitReached:true, error:'Bạn đã dùng đủ 5 câu hỏi hôm nay.', ...state });
        }
        const update = { quizDate:vietnamDayKey(), lastResetDate:vietnamDayKey(), walletUpdatedAt:new Date().toISOString() };
        if (kind === 'free') {
            if (state.quizFreeUsed) return res.status(409).json({ success:false, error:'Câu miễn phí hôm nay đã được dùng.', ...state });
            update.quizFreeUsed = true;
        } else {
            if (!state.quizFreeUsed) return res.status(400).json({ success:false, error:'Hãy dùng câu miễn phí trước.' });
            if (state.quizAdUnlocked >= QUIZ_AD_LIMIT) return res.status(429).json({ success:false, limitReached:true, error:'Đã mở đủ 4 câu bằng quảng cáo.' });
            update.quizAdUnlocked = state.quizAdUnlocked + 1;
        }
        const { error } = await saveUserFields(userId, update);
        if (error) throw error;
        res.json({ success:true, kind, walletUpdatedAt:update.walletUpdatedAt, ...quizState({ ...user, ...update }) });
    } catch (e) {
        console.error('Lỗi cấp lượt câu hỏi:', e);
        res.status(500).json({ success:false, error:e.message });
    } finally { quizProcessing.delete(userId); }
});




async function persistCanonicalMilestoneClaims(userId, userRow) {
    const extra = await getUserExtra(userId);
    const claims = referralMilestoneClaimMap(userRow, extra);
    const canonicalClaims = {};
    for (const reward of REFERRAL_MILESTONE_REWARDS) {
        if (claims[String(reward.friends)] === true) canonicalClaims[String(reward.friends)] = true;
    }
    const stored = (extra?.serverReferralMilestones && typeof extra.serverReferralMilestones === 'object' && !Array.isArray(extra.serverReferralMilestones))
        ? extra.serverReferralMilestones : {};
    if (JSON.stringify(stored) !== JSON.stringify(canonicalClaims)) {
        await saveUserExtra(userId, { serverReferralMilestones:canonicalClaims });
        await flushUserExtra();
    }
    return canonicalClaims;
}

app.get('/api/referral/milestones/:id', async (req,res) => {
    try {
        const userId = String(req.params.id || '');
        if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
        const user = await readUserRow(userId);
        if (!user.data) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        const claims = await persistCanonicalMilestoneClaims(userId, user.data);
        res.json({
            success:true,
            validInvites:Number(user.data.validInvites||0),
            milestones:canonicalReferralMilestones(claims)
        });
    } catch(e) { res.status(500).json({success:false,error:e.message}); }
});

const referralMilestoneProcessing = new Set();
app.post('/api/referral/milestone-claim', async (req,res) => {
    const userId = String(req.body?.userId || '');
    const friends = Number(req.body?.friends);
    if (!assertTelegramUser(req, userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    const localKey = `${userId}:${friends}`;
    if (referralMilestoneProcessing.has(localKey)) return res.status(409).json({success:false,retry:true,error:'Mốc đang được xử lý.'});
    referralMilestoneProcessing.add(localKey);
    let release = null;
    try {
        const reward = REFERRAL_MILESTONE_REWARDS.find(m => m.friends === friends);
        if (!reward) return res.status(400).json({success:false,error:'Mốc không hợp lệ.'});
        const fraudGate = await antiFraudRewardGate(userId);
        if (!fraudGate.allowed) return res.status(fraudGate.status).json({success:false,...fraudGate});

        release = await acquirePersistentLeaseLock(persistentEventKey('referral-milestone-lock', `${userId}:${friends}`), 30 * 1000);
        if (!release) return res.status(409).json({success:false,retry:true,error:'Mốc đang được xử lý ở phiên khác.'});

        let current = await readUserRow(userId);
        if (!current.data) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        if (Number(current.data.validInvites||0) < reward.friends) return res.status(400).json({success:false,error:'Chưa đủ bạn hợp lệ.'});
        let claims = await persistCanonicalMilestoneClaims(userId, current.data);
        if (claims[String(friends)] === true) {
            return res.json({success:true,alreadyClaimed:true,friends,reward:{...reward,reward:referralMilestoneRewardText(reward,'vi')},coins:Number(current.data.coins||0),orders:Number(current.data.orders||0),spins:Number(current.data.spins||0),walletUpdatedAt:current.data.walletUpdatedAt||null});
        }

        const payoutId = `referral-milestone:${userId}:${friends}`;
        const markerKey = persistentEventKey('referral-milestone-payout', `${userId}:${friends}`);
        let marker = await readPersistentEvent(markerKey);
        if (!marker) {
            const reservation = {
                status:'reserved', payoutId, userId, friends,
                reward:{coins:reward.coins,orders:reward.orders,spins:reward.spins},
                preCoins:Number(current.data.coins||0), preOrders:Number(current.data.orders||0), preSpins:Number(current.data.spins||0),
                targetCoins:Number(current.data.coins||0)+reward.coins,
                targetOrders:Number(current.data.orders||0)+reward.orders,
                targetSpins:Number(current.data.spins||0)+reward.spins,
                createdAt:Date.now()
            };
            const once = await createPersistentEventOnce(markerKey, reservation);
            if (once.error) throw once.error;
            marker = once.value || reservation;
        }

        if (marker.status !== 'committed') {
            current = await readUserRow(userId);
            if (!current.data) throw new Error('Không đọc được user khi claim mốc.');
            const alreadyApplied = String(current.data.lastReferralMilestonePayoutId||'') === payoutId
                || (marker.status === 'mutating'
                    && Number(current.data.coins||0) >= Number(marker.targetCoins||Number.MAX_SAFE_INTEGER)
                    && Number(current.data.orders||0) >= Number(marker.targetOrders||Number.MAX_SAFE_INTEGER)
                    && Number(current.data.spins||0) >= Number(marker.targetSpins||Number.MAX_SAFE_INTEGER));
            if (!alreadyApplied) {
                marker = {...marker,status:'mutating',mutatingAt:Date.now()};
                if (!(await writePersistentEvent(markerKey, marker, 4))) throw new Error('Không lưu được marker claim mốc.');
                const mutation = await atomicWalletMutation(userId, {
                    deltaCoins:reward.coins, deltaOrders:reward.orders, deltaSpins:reward.spins,
                    setFields:{lastReferralMilestonePayoutId:payoutId}
                });
                if (mutation.error) return res.status(409).json({success:false,retry:true,error:mutation.error.message});
                if (!(await flushUserExtra())) return res.status(503).json({success:false,retry:true,error:'Phần thưởng đã commit nhưng trạng thái đang đồng bộ.'});
            }
            current = await readUserRow(userId);
            if (!current.data) throw new Error('Không xác minh được ví sau khi claim mốc.');
            const safelyApplied = String(current.data.lastReferralMilestonePayoutId||'') === payoutId
                || (Number(current.data.coins||0) >= Number(marker.targetCoins||0)
                    && Number(current.data.orders||0) >= Number(marker.targetOrders||0)
                    && Number(current.data.spins||0) >= Number(marker.targetSpins||0));
            if (!safelyApplied) return res.status(503).json({success:false,retry:true,error:'Đang xác minh phần thưởng mốc.'});
            marker = {...marker,status:'committed',committedAt:marker.committedAt||Date.now()};
            if (!(await writePersistentEvent(markerKey,marker,4))) return res.status(503).json({success:false,retry:true,error:'Phần thưởng đã commit, marker đang đồng bộ.'});
        }

        current = await readUserRow(userId);
        claims = await persistCanonicalMilestoneClaims(userId, current.data || {});
        if (claims[String(friends)] !== true) {
            claims[String(friends)] = true;
            await saveUserExtra(userId,{serverReferralMilestones:claims});
            if (!(await flushUserExtra())) return res.status(503).json({success:false,retry:true,error:'Phần thưởng đã commit, trạng thái mốc đang đồng bộ.'});
        }

        if (!marker.transactionLogged) {
            const reasonBase = `Thưởng mốc ${friends} bạn | payout=${payoutId}`;
            if (reward.coins) {
                const reason = `${reasonBase} | coin`;
                const {data:tx}=await supabase.from('transactions').select('userId').eq('userId',userId).eq('reason',reason).limit(1);
                if (!tx?.length) await insertRowSafe('transactions',{userId,type:'coin',amount:reward.coins,reason});
            }
            if (reward.orders) {
                const reason = `${reasonBase} | orders`;
                const {data:tx}=await supabase.from('transactions').select('userId').eq('userId',userId).eq('reason',reason).limit(1);
                if (!tx?.length) await insertRowSafe('transactions',{userId,type:'orders',amount:reward.orders,reason});
            }
            marker={...marker,transactionLogged:true};
            await writePersistentEvent(markerKey,marker,3);
        }
        if (!marker.fraudLogged) {
            await recordAntiFraudEvent(userId,'task',{rewardEvent:true,coins:reward.coins,orders:reward.orders,spins:reward.spins});
            marker={...marker,fraudLogged:true};
            await writePersistentEvent(markerKey,marker,3);
        }
        if (!marker.notificationSent) {
            const sent = await safeSendLocalizedMessage(userId,
                `🎁 *NHẬN THƯỞNG MỐC ${friends} BẠN!*\n✅ +${referralMilestoneRewardText(reward,'vi')}`,
                `🎁 *${friends}-FRIEND MILESTONE REWARD!*\n✅ +${referralMilestoneRewardText(reward,'en')}`,
                {parse_mode:'Markdown'});
            if (sent) { marker={...marker,notificationSent:true}; await writePersistentEvent(markerKey,marker,2); }
        }
        const out = await readUserRow(userId);
        res.json({success:true,friends,reward:{...reward,reward:referralMilestoneRewardText(reward,'vi')},coins:Number(out.data?.coins||0),orders:Number(out.data?.orders||0),spins:Number(out.data?.spins||0),walletUpdatedAt:out.data?.walletUpdatedAt||null});
    } catch(e) { console.error('Lỗi claim referral milestone:',e); res.status(500).json({success:false,error:e.message}); }
    finally {
        referralMilestoneProcessing.delete(localKey);
        if (release) { try { await release(); } catch (_) {} }
    }
});

// ==================== SERVER-AUTHORITATIVE DAILY TASK / QUIZ REWARDS ====================
const TASK_REWARDS = {
    deliver1: { coins: 30, orders: 25, spins: 0 },
    deliver3: { coins: 40, orders: 40, spins: 0 },
    deliver5: { coins: 50, orders: 50, spins: 0 },
    watch3rewarded: { coins: 150, orders: 50, spins: 0 },
    smartlink5: { coins: 75, orders: 75, spins: 0 },
    spin1: { coins: 50, orders: 0, spins: 0 },
    invite1: { coins: 350, orders: 25, spins: 0 },
    invite5: { coins: 500, orders: 100, spins: 1 },
};
const DAILY_TASK_IDS = Object.keys(TASK_REWARDS);
const DAILY_TASK_ALL_REWARD = { coins: 1000, orders: 500, spins: 2 };

const dailyTaskLegacyClaimsCache = new Map();
let dailyTaskLegacyClaimsCacheDay = '';
async function getServerTaskClaims(userId) {
    const today = vietnamDayKey();
    if (dailyTaskLegacyClaimsCacheDay !== today) {
        dailyTaskLegacyClaimsCache.clear();
        dailyTaskLegacyClaimsCacheDay = today;
    }
    const extra = await getUserExtra(userId);
    const legacy = (extra?.serverTaskClaims && typeof extra.serverTaskClaims === 'object') ? { ...extra.serverTaskClaims } : {};
    // Marker chính của bản hiện tại nằm trong app_settings/serverTaskClaims. Migration #6 chỉ được đọc như
    // nguồn tương thích cũ. Cache theo user/ngày để không query lại cùng bảng legacy ở mọi lần bấm NHẬN.
    const claims = legacy.__date === today ? legacy : { __date: today };
    if (!SUPABASE_SERVICE_ROLE_KEY) return claims;
    const cacheKey = `${String(userId)}:${today}`;
    let legacyRows = dailyTaskLegacyClaimsCache.get(cacheKey);
    if (!legacyRows) {
        try {
            const { data, error } = await jobMailDb().from('daily_task_claims')
                .select('task_id,day_key').eq('user_id', String(userId)).eq('day_key', today);
            if (error) throw error;
            legacyRows = Array.isArray(data) ? data : [];
            dailyTaskLegacyClaimsCache.set(cacheKey, legacyRows);
        } catch (e) {
            if (!getServerTaskClaims._warned) {
                getServerTaskClaims._warned = true;
                console.warn('⚠️ DAILY TASK legacy RPC/table chưa khả dụng; đang dùng persistent payout marker:', e?.message || e);
            }
            legacyRows = [];
            dailyTaskLegacyClaimsCache.set(cacheKey, legacyRows);
        }
    }
    for (const row of legacyRows) if (row?.task_id) claims[String(row.task_id)] = today;
    return claims;
}
async function getDailyActionFlags(userId) {
    const extra = await getUserExtra(userId);
    const flags = extra?.dailyActionFlags;
    if (!flags || flags.__date !== vietnamDayKey()) return { __date: vietnamDayKey() };
    return { ...flags };
}

function dailyTaskDefinitions(user = {}, claims = {}, actionFlags = {}) {
    const today = vietnamDayKey();
    const rewardedAds = Number(user.rewardedAdsToday || 0);
    const delivery = Number(user.deliveryCount || 0);
    const smartlinks = Number(user.smartlinkCount || 0);
    const invites = Number(user.dailyValidInvites || 0);
    const defs = [
        { id:'deliver1', name:'🚚 Giao hàng 1 lần', icon:'🚚', max:1, progress:Math.min(delivery,1), eligible:delivery>=1 },
        { id:'deliver3', name:'🚚 Giao hàng 3 lần', icon:'🚚', max:3, progress:Math.min(delivery,3), eligible:delivery>=3 },
        { id:'deliver5', name:'🚚 Giao hàng 5 lần', icon:'🚚', max:5, progress:Math.min(delivery,5), eligible:delivery>=5 },
        { id:'watch3rewarded', name:'📺 Xem 3 QC (chỉ tính QC Rewarded Interstitial)', icon:'📺', max:3, progress:Math.min(rewardedAds,3), eligible:rewardedAds>=3 },
        { id:'smartlink5', name:'🔗 Hoàn thành 5 SmartLink', icon:'🔗', max:5, progress:Math.min(smartlinks,5), eligible:smartlinks>=5 },
        { id:'spin1', name:'🎁 Mở rương 1 lần', icon:'🎁', max:1, progress:Number(user.chestOpensToday||0)>=1?1:0, eligible:Number(user.chestOpensToday||0)>=1 },
        { id:'invite1', name:'👥 Mời 1 bạn thành công', icon:'👥', max:1, progress:Math.min(invites,1), eligible:invites>=1 },
        { id:'invite5', name:'👥 Mời 5 bạn thành công', icon:'👥', max:5, progress:Math.min(invites,5), eligible:invites>=5 },
    ];
    return defs.map(t => ({
        ...t,
        reward: TASK_REWARDS[t.id]?.coins || 0,
        rewardOrders: TASK_REWARDS[t.id]?.orders || 0,
        rewardSpins: TASK_REWARDS[t.id]?.spins || 0,
        once: t.max === 1,
        done: claims[t.id] === today,
        claimable: claims[t.id] !== today && t.eligible
    }));
}

function dailyTaskPayoutId(userId, dayKey, taskId) {
    return taskId === '__all'
        ? `daily-task-all:${String(dayKey)}:${String(userId)}`
        : `daily-task:${String(dayKey)}:${String(userId)}:${String(taskId)}`;
}
function dailyTaskPayoutField(taskId) {
    return taskId === '__all' ? 'lastDailyTaskAllPayoutId' : 'lastDailyTaskPayoutId';
}
function dailyTaskPayoutMarkerKey(userId, dayKey, taskId) {
    return persistentEventKey('daily-task-payout', dailyTaskPayoutId(userId, dayKey, taskId));
}
function dailyTaskPayoutLooksApplied(user, marker, payoutField, payoutId) {
    if (!user || !marker) return false;
    if (String(user[payoutField] || '') === String(payoutId)) return true;
    if (String(marker.status || '') !== 'mutating') return false;
    const walletAt = Date.parse(String(user.walletUpdatedAt || ''));
    const mutatingAt = Number(marker.mutatingAt || 0);
    if (mutatingAt > 0 && Number.isFinite(walletAt) && walletAt < mutatingAt) return false;
    return Number(user.coins || 0) >= Number(marker.targetCoins || 0)
        && Number(user.orders || 0) >= Number(marker.targetOrders || 0)
        && Number(user.spins || 0) >= Number(marker.targetSpins || 0);
}
async function persistDailyTaskClaim(userId, claims, taskId, today, flushNow = true) {
    const nextClaims = { ...(claims || {}), __date:today, [taskId]:today };
    await saveUserExtra(userId, { serverTaskClaims:nextClaims });
    if (flushNow && !(await flushUserExtra())) throw new Error('Không lưu được trạng thái Daily Task.');
    return nextClaims;
}
async function executeDailyTaskPayout(userId, taskId, reward, claims, today, initialUser = null) {
    const payoutId = dailyTaskPayoutId(userId, today, taskId);
    const markerKey = dailyTaskPayoutMarkerKey(userId, today, taskId);
    const payoutField = dailyTaskPayoutField(taskId);
    let marker = await readPersistentEvent(markerKey);
    let initial = initialUser || null;

    if (!marker) {
        if (!initial) {
            const current = await readUserRow(userId);
            if (current.error || !current.data) return { ok:false, reason:'database_temporarily_unavailable', error:current.error || new Error('Không tìm thấy user.') };
            initial = current.data;
        }
        const reservation = {
            status:'reserved', payoutId, userId:String(userId), taskId:String(taskId), dayKey:String(today),
            rewardCoins:Number(reward.coins || 0), rewardOrders:Number(reward.orders || 0), rewardSpins:Number(reward.spins || 0),
            preCoins:Number(initial.coins || 0), preOrders:Number(initial.orders || 0), preSpins:Number(initial.spins || 0),
            targetCoins:Number(initial.coins || 0) + Number(reward.coins || 0),
            targetOrders:Number(initial.orders || 0) + Number(reward.orders || 0),
            targetSpins:Number(initial.spins || 0) + Number(reward.spins || 0),
            createdAt:Date.now(), transactionLogged:false, fraudLogged:false
        };
        const once = await createPersistentEventOnce(markerKey, reservation);
        if (once.error || !once.value) return { ok:false, reason:'database_temporarily_unavailable', error:once.error || new Error('Không tạo được payout marker.') };
        marker = once.value;
    }

    if (String(marker.status || '') === 'committed') {
        const nextClaims = await persistDailyTaskClaim(userId, claims, taskId, today);
        let freshData = initial;
        if (!freshData || !dailyTaskPayoutLooksApplied(freshData, marker, payoutField, payoutId)) {
            const fresh = await readUserRow(userId);
            if (fresh.error || !fresh.data) return { ok:false, reason:'database_temporarily_unavailable', error:fresh.error || new Error('Không đọc được ví mới.') };
            freshData = fresh.data;
        }
        return { ok:true, alreadyClaimed:true, payoutId, dayKey:today, marker, claims:nextClaims, user:freshData };
    }

    let currentData = initial;
    if (!currentData) {
        const current = await readUserRow(userId);
        if (current.error || !current.data) return { ok:false, reason:'database_temporarily_unavailable', error:current.error || new Error('Không đọc được user.') };
        currentData = current.data;
    }

    let alreadyApplied = dailyTaskPayoutLooksApplied(currentData, marker, payoutField, payoutId);
    let nextClaims = null;
    if (!alreadyApplied) {
        marker = { ...marker, status:'mutating', mutatingAt:Date.now() };
        if (!(await writePersistentEvent(markerKey, marker, 4))) {
            return { ok:false, reason:'database_temporarily_unavailable', error:new Error('Không persist được payout marker trước khi cộng thưởng.') };
        }

        const mutation = await atomicWalletMutation(userId, {
            deltaCoins:Number(reward.coins || 0),
            deltaOrders:Number(reward.orders || 0),
            deltaSpins:Number(reward.spins || 0),
            setFields:{ [payoutField]:payoutId }
        });
        if (mutation.error) return { ok:false, reason:'database_temporarily_unavailable', error:mutation.error };

        // Gộp payout-field fallback + serverTaskClaims vào CÙNG một lần flush user_extra_state để giảm latency.
        // Wallet đã commit bằng CAS trước bước này; nếu process chết trước flush, marker "mutating" + target balance
        // vẫn cho phép recovery mà không cộng lần hai.
        nextClaims = await persistDailyTaskClaim(userId, claims, taskId, today, false);
        if (!(await flushUserExtra())) {
            return { ok:false, reason:'database_temporarily_unavailable', error:new Error('Phần thưởng đã xử lý nhưng trạng thái payout/claim chưa flush xong.') };
        }

        const fresh = await readUserRow(userId);
        if (fresh.error || !fresh.data) return { ok:false, reason:'database_temporarily_unavailable', error:fresh.error || new Error('Không xác minh được ví sau payout.') };
        currentData = fresh.data;
        alreadyApplied = dailyTaskPayoutLooksApplied(currentData, marker, payoutField, payoutId);
        if (!alreadyApplied) {
            return { ok:false, reason:'database_temporarily_unavailable', error:new Error('Không xác minh được trạng thái payout sau khi cập nhật ví.') };
        }
    } else {
        nextClaims = await persistDailyTaskClaim(userId, claims, taskId, today);
    }

    marker = { ...marker, status:'committed', committedAt:marker.committedAt || Date.now(), walletUpdatedAt:currentData.walletUpdatedAt || null };
    if (!(await writePersistentEvent(markerKey, marker, 4))) {
        // Payout + claim đã persist nên tuyệt đối không rollback/cộng lại. Lần sau payoutId/serverTaskClaims sẽ recover.
        console.warn(`⚠️ Daily Task payout ${payoutId} đã cộng và claim nhưng chưa cập nhật được marker committed.`);
    }
    return { ok:true, alreadyClaimed:false, payoutId, dayKey:today, marker, claims:nextClaims, user:currentData };
}
async function finalizeDailyTaskAudit(userId, taskId, reward, payoutResult, reasonLabel) {
    if (!payoutResult?.ok || payoutResult.alreadyClaimed) return;
    let marker = payoutResult.marker || {};
    const markerKey = dailyTaskPayoutMarkerKey(userId, payoutResult.dayKey || vietnamDayKey(), taskId);
    if (!marker.fraudLogged) {
        await recordAntiFraudEvent(userId,'task',{ rewardEvent:true, coins:reward.coins, orders:reward.orders, spins:reward.spins });
        marker = { ...marker, fraudLogged:true };
        await writePersistentEvent(markerKey, marker, 2).catch(() => false);
    }
    if (!marker.transactionLogged) {
        const reason = `${reasonLabel} | payout=${payoutResult.payoutId}`;
        if (reward.coins) await logTransaction(userId,'coin',reward.coins,reason);
        if (reward.orders) await logTransaction(userId,'orders',reward.orders,reason);
        marker = { ...marker, transactionLogged:true };
        await writePersistentEvent(markerKey, marker, 2).catch(() => false);
    }
}

const taskClaimProcessing = new Set();
async function claimServerTask(userId, taskId) {
    const lockKey = `daily:${String(userId)}`;
    if (taskClaimProcessing.has(lockKey)) return { ok:false, reason:'processing' };
    taskClaimProcessing.add(lockKey);
    let releasePersistentTaskLock = null;
    try {
        releasePersistentTaskLock = await acquirePersistentLeaseLock(persistentEventKey('daily-task-user-lock', String(userId)),60*1000);
        if (!releasePersistentTaskLock) return {ok:false,reason:'processing'};

        // Hai nhánh này độc lập; chạy song song để giảm round-trip trước khi đánh giá task.
        const [fraudGate,user] = await Promise.all([
            antiFraudRewardGate(userId),
            loadCurrentDailyUser(userId)
        ]);
        if (!fraudGate.allowed) return { ok:false, reason:'fraud_hold', fraudGate };
        if (!user) return { ok:false, reason:'user_not_found' };
        if (user.isBanned) return { ok:false, reason:'banned' };
        if (!TASK_REWARDS[taskId]) return { ok:false, reason:'unsupported_task' };

        const today = vietnamDayKey();
        const [rawClaims,actionFlags] = await Promise.all([
            getServerTaskClaims(userId),
            getDailyActionFlags(userId)
        ]);
        const claims = { ...rawClaims, __date:today };
        const reward = TASK_REWARDS[taskId];

        if (claims[taskId] === today) {
            return {
                ok:true, taskId, reward, alreadyClaimed:true, user,
                tasks:dailyTaskDefinitions(user,claims,actionFlags),
                walletUpdatedAt:user.walletUpdatedAt || null
            };
        }

        const task = dailyTaskDefinitions(user, claims, actionFlags).find(t => t.id === taskId);
        if (!task || !task.eligible) return { ok:false, reason:'not_eligible' };

        const payout = await executeDailyTaskPayout(userId, taskId, reward, claims, today, user);
        if (!payout.ok) return payout;

        const committedClaims = payout.claims || { ...claims, [taskId]:today };
        const freshUser = payout.user || user;
        // Audit không nằm trên critical path của số dư/claim; marker fraudLogged/transactionLogged giữ idempotency.
        void finalizeDailyTaskAudit(userId, taskId, reward, payout, `Nhiệm vụ ${taskId}`)
            .catch(e => console.error('Daily Task audit:', e?.message || e));

        return {
            ok:true, taskId, reward, alreadyClaimed:!!payout.alreadyClaimed,
            user:freshUser, tasks:dailyTaskDefinitions(freshUser,committedClaims,actionFlags),
            walletUpdatedAt:freshUser?.walletUpdatedAt || new Date().toISOString()
        };
    } finally {
        if (releasePersistentTaskLock) { try { await releasePersistentTaskLock(); } catch (_) {} }
        taskClaimProcessing.delete(lockKey);
    }
}

app.get('/api/daily-tasks/status/:id', async (req,res) => {
    const userId = String(req.params.id||'');
    if (!assertTelegramUser(req,userId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    try {
        const user = await loadCurrentDailyUser(userId);
        if (!user) return res.status(404).json({success:false,error:'Không tìm thấy user.'});
        const [claims,flags] = await Promise.all([getServerTaskClaims(userId),getDailyActionFlags(userId)]);
        const tasks = dailyTaskDefinitions(user,claims,flags);
        const today = vietnamDayKey();
        const allTasksClaimed = claims.__all === today;
        const allDone = tasks.every(t => t.done);
        res.json({ success:true, today, lastResetDate:user.lastResetDate||today, tasks, allDone, allTasksClaimed, rewardedAdsToday:Number(user.rewardedAdsToday||0), deliveryCount:Number(user.deliveryCount||0), deliveryLimit:DELIVERY_DAILY_LIMIT, extraDeliveryAdsToday:Number(user.extraDeliveryAdsToday||0), extraDeliveryCount:Number(user.extraDeliveryCount||0), smartlinkCount:Number(user.smartlinkCount||0), smartlinksToday:Number(user.smartlinksToday||0), dailyValidInvites:Number(user.dailyValidInvites||0), coins:Number(user.coins||0), orders:Number(user.orders||0), spins:Number(user.spins||0), walletUpdatedAt:user.walletUpdatedAt||null });
    } catch(e) {
        console.error('Daily Task status:', e?.message || e);
        res.status(500).json({success:false,code:'database_temporarily_unavailable',error:'Hệ thống nhiệm vụ đang tạm bận. Vui lòng thử lại.'});
    }
});

app.post('/api/task/claim', async (req,res) => {
    const authUserId = String(req.body?.userId || '');
    if (!assertTelegramUser(req, authUserId)) return res.status(401).json({success:false,code:'auth_invalid',error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res)) return;
    try {
        const userId = authUserId;
        const taskId = String(req.body?.taskId || '');
        if (!userId || !taskId) return res.status(400).json({success:false,code:'invalid_request',error:'Thiếu userId/taskId.'});
        const result = await claimServerTask(userId,taskId);
        if (!result.ok) {
            if (result.reason==='processing') return res.status(409).json({success:false,code:'processing',retry:true,error:'Phần thưởng đang được xử lý. Vui lòng chờ một chút.'});
            if (result.reason==='fraud_hold') return res.status(result.fraudGate.status).json({success:false,code:'fraud_hold',...result.fraudGate,verificationRequired:true});
            if (result.reason==='not_eligible') return res.status(409).json({success:false,code:'not_eligible',error:'Máy chủ chưa xác nhận bạn hoàn thành nhiệm vụ.'});
            if (result.reason==='banned') return res.status(403).json({success:false,code:'account_blocked',error:'Tài khoản hiện đang bị khóa.'});
            if (result.reason==='user_not_found') return res.status(404).json({success:false,code:'user_not_found',error:'Không tìm thấy người dùng.'});
            if (result.reason==='unsupported_task') return res.status(400).json({success:false,code:'unsupported_task',error:'Nhiệm vụ không hợp lệ.'});
            if (result.reason==='database_temporarily_unavailable') {
                console.error('Daily Task persistent payout failed:', result.error?.message || result.error || 'unknown');
                return res.status(503).json({success:false,code:'database_temporarily_unavailable',retry:true,error:'Hệ thống phần thưởng đang tạm bận. Vui lòng thử lại.'});
            }
            return res.status(400).json({success:false,code:String(result.reason||'task_failed'),error:'Không thể nhận phần thưởng nhiệm vụ lúc này.'});
        }
        const user = result.user || (await readUserRow(userId)).data;
        const tasks = Array.isArray(result.tasks)
            ? result.tasks
            : dailyTaskDefinitions(user||{}, ...(await Promise.all([getServerTaskClaims(userId),getDailyActionFlags(userId)])));
        res.json({success:true,alreadyClaimed:!!result.alreadyClaimed,reward:result.reward,taskId,tasks,coins:Number(user?.coins||0),orders:Number(user?.orders||0),spins:Number(user?.spins||0),walletUpdatedAt:user?.walletUpdatedAt||result.walletUpdatedAt||null});
    } catch(e) {
        console.error('Daily Task claim:', e?.message || e);
        res.status(500).json({success:false,code:'database_temporarily_unavailable',error:'Hệ thống phần thưởng đang tạm bận. Vui lòng thử lại.'});
    }
});

app.post('/api/task/claim-all', async (req,res) => {
    const userId=String(req.body?.userId||'');
    if(!assertTelegramUser(req,userId)) return res.status(401).json({success:false,code:'auth_invalid',error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res)) return;
    const lockKey=`daily:${userId}`;
    if(taskClaimProcessing.has(lockKey)) return res.status(409).json({success:false,code:'processing',retry:true,error:'Phần thưởng đang được xử lý. Vui lòng chờ một chút.'});
    taskClaimProcessing.add(lockKey);
    let releasePersistentTaskLock=null;
    try {
        releasePersistentTaskLock=await acquirePersistentLeaseLock(persistentEventKey('daily-task-user-lock',String(userId)),60*1000);
        if(!releasePersistentTaskLock) return res.status(409).json({success:false,code:'processing',retry:true,error:'Phần thưởng đang được xử lý trên một phiên khác.'});

        const [fraudGate,user]=await Promise.all([
            antiFraudRewardGate(userId),
            loadCurrentDailyUser(userId)
        ]);
        if(!fraudGate.allowed) return res.status(fraudGate.status).json({success:false,code:'fraud_hold',...fraudGate,verificationRequired:true});
        if(!user) return res.status(404).json({success:false,code:'user_not_found',error:'Không tìm thấy người dùng.'});

        const today=vietnamDayKey();
        const [rawClaims,actionFlags]=await Promise.all([getServerTaskClaims(userId),getDailyActionFlags(userId)]);
        const claims={...rawClaims,__date:today};
        const defs=dailyTaskDefinitions(user,claims,actionFlags);
        if(defs.some(t=>claims[t.id]!==today)) return res.status(409).json({success:false,code:'not_eligible',error:'Chưa hoàn thành toàn bộ nhiệm vụ hôm nay.'});
        if(claims.__all===today) {
            return res.json({
                success:true,alreadyClaimed:true,tasks:defs,allTasksClaimed:true,
                coins:Number(user.coins||0),orders:Number(user.orders||0),spins:Number(user.spins||0),walletUpdatedAt:user.walletUpdatedAt||null
            });
        }

        const reward=DAILY_TASK_ALL_REWARD;
        const payout=await executeDailyTaskPayout(userId,'__all',reward,claims,today,user);
        if(!payout.ok) {
            console.error('Daily Task claim-all persistent payout failed:', payout.error?.message || payout.error || payout.reason);
            return res.status(503).json({success:false,code:'database_temporarily_unavailable',retry:true,error:'Hệ thống phần thưởng đang tạm bận. Vui lòng thử lại.'});
        }
        void finalizeDailyTaskAudit(userId,'__all',reward,payout,'Thưởng hoàn thành tất cả nhiệm vụ ngày')
            .catch(e=>console.error('Daily Task claim-all audit:',e?.message||e));
        const fresh=payout.user || user;
        return res.json({
            success:true,alreadyClaimed:!!payout.alreadyClaimed,reward,tasks:defs,allTasksClaimed:true,
            coins:Number(fresh?.coins||0),orders:Number(fresh?.orders||0),spins:Number(fresh?.spins||0),walletUpdatedAt:fresh?.walletUpdatedAt||null
        });
    } catch(e) {
        console.error('Daily Task claim-all:',e?.message||e);
        return res.status(500).json({success:false,code:'database_temporarily_unavailable',error:'Hệ thống phần thưởng đang tạm bận. Vui lòng thử lại.'});
    } finally {
        if(releasePersistentTaskLock){try{await releasePersistentTaskLock();}catch(_){}}
        taskClaimProcessing.delete(lockKey);
    }
});

// ==================== NHIỆM VỤ "THAM GIA NHÓM" — VERSIONED CAMPAIGN ====================
// Chỉ campaign đang active mới nằm trong GROUP_TASK_CAMPAIGNS. Historical marker/claim của campaign cũ
// vẫn được giữ nguyên trong Supabase/app_settings; không migrate, không reset và không trừ lại phần thưởng.
const GROUP_TASK_CAMPAIGN_ID = 'kiemtienmuakfc_2026_09';
const GROUP_TASK_CAMPAIGNS = Object.freeze({
    kiemtienmuakfc_2026_09: Object.freeze({
        id:'kiemtienmuakfc_2026_09', username:'@kiemtienmuakfc',
        joinUrl:'https://t.me/kiemtienmuakfc', reward:Object.freeze({coins:200,orders:200})
    })
});
const GROUP_TASK_PROCESS_ID = crypto.randomBytes(8).toString('hex');

function getGroupTaskCampaign(campaignId = GROUP_TASK_CAMPAIGN_ID) {
    return GROUP_TASK_CAMPAIGNS[String(campaignId || GROUP_TASK_CAMPAIGN_ID)] || null;
}
function groupTaskCampaignEventKey(userId, campaignId = GROUP_TASK_CAMPAIGN_ID) {
    return persistentEventKey('group-task-campaign', `${String(campaignId)}:${String(userId)}`);
}
function normalizeGroupTaskCampaignClaims(value) {
    return (value && typeof value === 'object' && !Array.isArray(value)) ? { ...value } : {};
}
async function markGroupTaskCampaignClaimed(userId, campaignId = GROUP_TASK_CAMPAIGN_ID) {
    const campaign = getGroupTaskCampaign(campaignId);
    if (!campaign) return false;
    const extra = await getUserExtra(userId);
    const claims = normalizeGroupTaskCampaignClaims(extra?.groupTaskCampaignClaims);
    if (claims[campaign.id] === true) return true;
    claims[campaign.id] = true;
    await saveUserExtra(userId, { groupTaskCampaignClaims: claims });
    return flushUserExtra();
}
async function isGroupTaskCampaignClaimed(userId, campaignId = GROUP_TASK_CAMPAIGN_ID) {
    const campaign = getGroupTaskCampaign(campaignId);
    if (!campaign) return false;
    const extra = await getUserExtra(userId);
    const claims = normalizeGroupTaskCampaignClaims(extra?.groupTaskCampaignClaims);
    if (claims[campaign.id] === true) return true;
    const marker = await readPersistentEvent(groupTaskCampaignEventKey(userId, campaign.id));
    if (marker?.status === 'committed') {
        await markGroupTaskCampaignClaimed(userId, campaign.id);
        return true;
    }
    return false;
}
async function checkTaskGroupMembership(userId, campaignId = GROUP_TASK_CAMPAIGN_ID) {
    const campaign = getGroupTaskCampaign(campaignId);
    if (!campaign) return {checked:false,isMember:false,status:'invalid_campaign',error:'Campaign không hợp lệ.'};
    try {
        const member = await bot.telegram.getChatMember(campaign.username, userId);
        const status = member?.status || 'unknown';
        const isMember = ['member','administrator','creator'].includes(status)
            || (status === 'restricted' && member?.is_member === true);
        return {checked:true,isMember,status};
    } catch (e) {
        console.error(`Lỗi check thành viên ${campaign.username} cho ${userId}:`, e?.message || e);
        return {checked:false,isMember:false,status:'error',error:e?.message || 'Telegram Bot API không thể xác minh thành viên.'};
    }
}
const groupTaskProcessing = new Set();

async function ensureGroupTaskTransactionLog(userId, reward, campaign) {
    const reason = `Nhiệm vụ Tham gia nhóm ${campaign.username} | campaign=${campaign.id}`;
    for (const [type, amount] of [['coin', reward.coins], ['orders', reward.orders]]) {
        const { data: rows, error } = await supabase.from('transactions')
            .select('userId').eq('userId', String(userId)).eq('type', type).eq('reason', reason).limit(1);
        if (error) return false;
        if (!rows || rows.length === 0) {
            const written = await insertRowSafe('transactions', {
                userId:String(userId),type,amount,reason,campaignId:campaign.id
            });
            if (written.error) return false;
        }
    }
    return true;
}

async function claimGroupTask(userId, campaignId = GROUP_TASK_CAMPAIGN_ID) {
    const campaign = getGroupTaskCampaign(campaignId);
    if (!campaign) return {ok:false,reason:'invalid_campaign'};
    const key = `${String(userId)}:${campaign.id}`;
    if (groupTaskProcessing.has(key)) return {ok:false,reason:'processing'};
    groupTaskProcessing.add(key);
    let releasePersistentLock = null;
    try {
        const fraudGate = await antiFraudRewardGate(userId);
        if (!fraudGate.allowed) return {ok:false,reason:'fraud_hold',fraudGate};

        let { data:user, error:userErr } = await readUserRow(userId);
        if (userErr || !user) return {ok:false,reason:'user_not_found'};
        if (user.isBanned) return {ok:false,reason:'banned'};
        if (await isGroupTaskCampaignClaimed(userId, campaign.id)) return {ok:false,reason:'already_claimed',campaign};

        const membership = await checkTaskGroupMembership(userId, campaign.id);
        if (!membership.checked) return {ok:false,reason:'membership_check_failed',membershipError:membership.error,campaign};
        if (!membership.isMember) return {ok:false,reason:'not_member',memberStatus:membership.status,campaign};

        // Cross-instance per-user lease: two different group campaigns can never mutate the same wallet concurrently.
        releasePersistentLock = await acquirePersistentLeaseLock(
            persistentEventKey('group-task-user-lock', String(userId)),
            60 * 1000
        );
        if (!releasePersistentLock) return {ok:false,reason:'processing',campaign};

        ({data:user,error:userErr} = await readUserRow(userId));
        if (userErr || !user) return {ok:false,reason:'user_not_found'};
        if (await isGroupTaskCampaignClaimed(userId, campaign.id)) return {ok:false,reason:'already_claimed',campaign};

        const markerKey = groupTaskCampaignEventKey(userId, campaign.id);
        const payoutId = `group-task:${campaign.id}:${String(userId)}`;
        let marker = await readPersistentEvent(markerKey);
        let createdByThisProcess = false;

        if (!marker) {
            const reservation = {
                status:'reserved',payoutId,campaignId:campaign.id,userId:String(userId),
                coins:campaign.reward.coins,orders:campaign.reward.orders,
                preCoins:Number(user.coins || 0),preOrders:Number(user.orders || 0),
                targetCoins:Number(user.coins || 0)+campaign.reward.coins,
                targetOrders:Number(user.orders || 0)+campaign.reward.orders,
                owner:GROUP_TASK_PROCESS_ID,reservedAt:Date.now(),leaseUntil:Date.now()+60*1000,
                fraudLogged:false,transactionLogged:false
            };
            const once = await createPersistentEventOnce(markerKey, reservation);
            if (once.error) return {ok:false,reason:'claim_marker_error',error:once.error,campaign};
            marker = once.value || reservation;
            createdByThisProcess = !!once.created;
        }

        if (marker.status === 'committed') {
            await markGroupTaskCampaignClaimed(userId, campaign.id);
            return {ok:false,reason:'already_claimed',campaign};
        }
        if (!createdByThisProcess && marker.owner && marker.owner !== GROUP_TASK_PROCESS_ID
            && Number(marker.leaseUntil || 0) > Date.now()) {
            return {ok:false,reason:'processing',campaign};
        }

        ({data:user,error:userErr} = await readUserRow(userId));
        if (userErr || !user) return {ok:false,reason:'user_not_found'};

        // Nếu marker reserved cũ chưa mutate và reward cấu hình thay đổi, đồng bộ marker theo campaign active.
        if (marker.status === 'reserved'
            && String(user.lastGroupTaskCampaignPayoutId || '') !== payoutId
            && (Number(marker.coins || 0) !== campaign.reward.coins || Number(marker.orders || 0) !== campaign.reward.orders)) {
            marker = {
                ...marker,coins:campaign.reward.coins,orders:campaign.reward.orders,
                preCoins:Number(user.coins || 0),preOrders:Number(user.orders || 0),
                targetCoins:Number(user.coins || 0)+campaign.reward.coins,
                targetOrders:Number(user.orders || 0)+campaign.reward.orders,
                owner:GROUP_TASK_PROCESS_ID,leaseUntil:Date.now()+60*1000
            };
            if (!(await writePersistentEvent(markerKey, marker, 4))) return {ok:false,reason:'claim_marker_error',campaign};
        }

        const alreadyApplied = String(user.lastGroupTaskCampaignPayoutId || '') === payoutId
            || (marker.status === 'mutating'
                && Number(user.coins || 0) >= Number(marker.targetCoins || Number.MAX_SAFE_INTEGER)
                && Number(user.orders || 0) >= Number(marker.targetOrders || Number.MAX_SAFE_INTEGER));

        if (!alreadyApplied) {
            marker = {...marker,status:'mutating',owner:GROUP_TASK_PROCESS_ID,mutatingAt:Date.now(),leaseUntil:Date.now()+60*1000};
            if (!(await writePersistentEvent(markerKey, marker, 4))) return {ok:false,reason:'claim_marker_error',campaign};
            const mutation = await atomicWalletMutation(userId, {
                deltaCoins:Number(marker.coins || campaign.reward.coins),
                deltaOrders:Number(marker.orders || campaign.reward.orders),
                setFields:{lastGroupTaskCampaignPayoutId:payoutId}
            });
            if (mutation.error) {
                console.error(`Lỗi cộng thưởng nhiệm vụ nhóm ${campaign.id}:`, mutation.error.message);
                return {ok:false,reason:'wallet_update_failed',error:mutation.error,campaign};
            }
        }

        const {data:verified,error:verifyError} = await readUserRow(userId);
        if (verifyError || !verified
            || Number(verified.coins || 0) < Number(marker.targetCoins || 0)
            || Number(verified.orders || 0) < Number(marker.targetOrders || 0)) {
            return {ok:false,reason:'wallet_verify_failed',campaign};
        }

        marker = {...marker,status:'committed',owner:GROUP_TASK_PROCESS_ID,committedAt:marker.committedAt||Date.now(),leaseUntil:0};
        if (!(await writePersistentEvent(markerKey, marker, 4))) return {ok:false,reason:'claim_marker_error',campaign};
        await markGroupTaskCampaignClaimed(userId, campaign.id);

        const actualReward = {coins:Number(marker.coins || campaign.reward.coins),orders:Number(marker.orders || campaign.reward.orders)};
        if (!marker.fraudLogged) {
            await recordAntiFraudEvent(userId,'task',{rewardEvent:true,coins:actualReward.coins,orders:actualReward.orders,campaignId:campaign.id});
            marker.fraudLogged = true;
            await writePersistentEvent(markerKey, marker, 2);
        }
        if (!marker.transactionLogged) {
            if (await ensureGroupTaskTransactionLog(userId, actualReward, campaign)) {
                marker.transactionLogged = true;
                await writePersistentEvent(markerKey, marker, 2);
            }
        }

        const {data:fresh} = await readUserRow(userId);
        return {ok:true,reward:actualReward,campaignId:campaign.id,coins:fresh?.coins||0,orders:fresh?.orders||0,walletUpdatedAt:fresh?.walletUpdatedAt||null};
    } finally {
        if (releasePersistentLock) {
            try { await releasePersistentLock(); } catch (_) {}
        }
        groupTaskProcessing.delete(key);
    }
}

app.post('/api/task/group/claim', async (req, res) => {
    const authUserId = String(req.body?.userId || '');
    if (!assertTelegramUser(req, authUserId)) return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    const requestedCampaignId = String(req.body?.campaignId || GROUP_TASK_CAMPAIGN_ID);
    const campaign = getGroupTaskCampaign(requestedCampaignId);
    if (!campaign) return res.status(400).json({success:false,error:'invalid_campaign'});
    try {
        const result = await claimGroupTask(authUserId, campaign.id);
        if (!result.ok) {
            if (result.reason === 'already_claimed') {
                return res.json({success:true,alreadyClaimed:true,campaignId:campaign.id});
            }
            if (result.reason === 'processing') return res.status(409).json({success:false,retry:true,error:'Đang xử lý, vui lòng thử lại.'});
            if (result.reason === 'not_member') return res.status(400).json({success:false,error:'not_member'});
            if (result.reason === 'membership_check_failed') {
                return res.status(503).json({
                    success:false,error:'membership_check_failed',
                    message:`Không thể xác minh thành viên ${campaign.username} qua Telegram Bot API. Bot cần có quyền phù hợp trong nhóm.`
                });
            }
            if (result.reason === 'fraud_hold') {
                return res.status(result.fraudGate.status).json({success:false,...result.fraudGate,verificationRequired:true});
            }
            return res.status(400).json({success:false,error:result.reason});
        }
        return res.json({
            success:true,reward:result.reward,campaignId:result.campaignId,
            coins:result.coins,orders:result.orders,walletUpdatedAt:result.walletUpdatedAt
        });
    } catch (e) {
        console.error('Lỗi claim nhiệm vụ nhóm:', e);
        return res.status(500).json({success:false,error:e.message});
    }
});


