function makeAdToken() { return `${Date.now()}_${Math.random().toString(36).slice(2,12)}`; }

// Persistent idempotency records for server-authoritative Rewarded actions and SmartLink.
const PERSISTENT_EVENT_PREFIX = 'reward_event:';
async function readPersistentEvent(key) {
    try {
        const { data, error } = await supabase.from('app_settings').select('value').eq('key', key).maybeSingle();
        if (error || !data?.value) return null;
        if (typeof data.value === 'string') {
            try { return JSON.parse(data.value); } catch (_) { return null; }
        }
        return (typeof data.value === 'object' && !Array.isArray(data.value)) ? data.value : null;
    } catch (e) {
        console.error('Persistent reward event read failed:', e.message);
        return null;
    }
}
async function writePersistentEvent(key, value, retries = 2) {
    for (let attempt = 0; attempt <= retries; attempt++) {
        try {
            const { error } = await supabase.from('app_settings').upsert({ key, value }, { onConflict: 'key' });
            if (!error) return true;
        } catch (_) {}
        if (attempt < retries) await new Promise(r => setTimeout(r, 150 * (attempt + 1)));
    }
    console.error('Persistent reward event write failed:', key);
    return false;
}
async function createPersistentEventOnce(key, value) {
    try {
        const { error } = await supabase.from('app_settings').insert({ key, value });
        if (!error) return { created: true, value, error: null };
        if (error.code === '23505') {
            const existing = await readPersistentEvent(key);
            return existing
                ? { created: false, value: existing, error: null }
                : { created: false, value: null, error: new Error(`Marker ${key} đã tồn tại nhưng chưa đọc lại được.`) };
        }
        return { created: false, value: null, error };
    } catch (error) {
        return { created: false, value: null, error };
    }
}
function persistentEventKey(type, id) {
    return `${PERSISTENT_EVENT_PREFIX}${type}:${String(id)}`;
}

async function acquirePersistentLeaseLock(lockKey, leaseMs = 60 * 1000) {
    const owner = `${process.pid}:${crypto.randomBytes(10).toString('hex')}`;
    const ttl = Math.max(5000, Number(leaseMs || 0));
    for (let attempt = 0; attempt < 5; attempt++) {
        const lockValue = {status:'locked',owner,lockedAt:Date.now(),leaseUntil:Date.now()+ttl};
        const once = await createPersistentEventOnce(lockKey, lockValue);
        if (!once.error && once.created) {
            let released = false;
            return async () => {
                if (released) return;
                released = true;
                try {
                    // app_settings.value là jsonb: xoá có điều kiện theo owner ngay trong DB để vừa giảm 1 round-trip
                    // vừa tránh race read->delete làm xoá nhầm lease mới của instance khác.
                    await supabase.from('app_settings').delete().eq('key', lockKey).contains('value', { owner });
                } catch (_) {}
            };
        }
        if (once.error) return null;
        const existing = once.value || await readPersistentEvent(lockKey);
        if (!existing || existing.status === 'released' || Number(existing.leaseUntil || 0) <= Date.now()) {
            try {
                if (existing?.owner) {
                    await supabase.from('app_settings').delete().eq('key', lockKey).contains('value', { owner:String(existing.owner) });
                } else if (!existing) {
                    // Không có row để dọn; vòng sau thử insert lại ngay.
                }
            } catch (_) {}
            await new Promise(r => setTimeout(r, 40 + attempt * 30));
            continue;
        }
        return null;
    }
    return null;
}


