function linkTaskNeedsRequestIp(cfg){
    return !!(cfg && (Number(cfg.maxPerIp||0)>0 || Number(cfg.maxPerDeviceIp||0)>0));
}
function linkTaskUnavailableState(cfg,runtime={}){
    if(!cfg) return {code:'provider_unsupported',message:'Nhiệm vụ này chưa được hỗ trợ.'};
    if(!linkTaskProviderConfigured(cfg)) return {code:'missing_provider_token',message:'Nhiệm vụ này đang được cấu hình trên máy chủ. Vui lòng thử lại sau.'};
    if(!SUPABASE_SERVICE_ROLE_KEY) return {code:'missing_service_role',message:'Hệ thống nhiệm vụ đang được cấu hình. Vui lòng thử lại sau.'};
    // device_hash trong schema hiện tại cũng dùng cùng secret HMAC, vì vậy Link Task cần secret này ngay cả
    // khi provider chỉ giới hạn theo thiết bị.
    if(!IP_HASH_SECRET) return {code:'missing_ip_hash_secret',message:'Hệ thống xác minh lượt nhiệm vụ đang được cấu hình. Vui lòng thử lại sau.'};
    if(linkTaskNeedsRequestIp(cfg) && runtime.ipAvailable === false) return {code:'ip_unavailable',message:'Tạm thời chưa xác định được IP kết nối cho nhiệm vụ này.'};
    return {code:'',message:''};
}
function linkTaskUnavailableReason(cfg,runtime={}){
    return linkTaskUnavailableState(cfg,runtime).message;
}
function linkTaskDbErrorState(error){
    const code=String(error?.code||'').toUpperCase();
    const message=String(error?.message||error||'').toLowerCase();
    const mentionsLinkTaskObject = message.includes('link_task_attempts') || message.includes('link_task_reward_atomic') || message.includes('link_task_verify_code_atomic');
    const schemaMissing = ['42P01','42703','42883','PGRST202','PGRST204','PGRST205'].includes(code)
        || (mentionsLinkTaskObject && (
            message.includes('does not exist') ||
            message.includes('could not find') ||
            message.includes('schema cache') ||
            message.includes('not found')
        ));
    if(schemaMissing){
        return {code:'link_task_db_not_ready',message:'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'};
    }
    if(code==='42501' || message.includes('permission denied')){
        return {code:'link_task_db_access_denied',message:'Hệ thống nhiệm vụ đang được hoàn tất cấu hình quyền truy cập. Vui lòng thử lại sau.'};
    }
    return null;
}

const LINK_TASK_DB_COLUMNS = Object.freeze([
    'id','nonce','user_id','provider','task_id','status','reward_orders','day_key',
    'issued_ip_hash','landing_ip_hash','device_hash','device_ip_hash','country_code','is_vpn',
    'short_url','provider_slug','provider_view_baseline','created_at','expires_at',
    'landed_at','confirmed_at','rewarded_at','verify_last_attempt_at','verify_attempt_count','metadata'
]);
const LINK_TASK_DB_READY_TTL_MS = 60 * 1000;
const LINK_TASK_DB_NOT_READY_TTL_MS = 30 * 1000;
let linkTaskDbReadinessCache = null;
let linkTaskDbReadinessPromise = null;

function linkTaskDbDiagnosticCode(error){
    const raw=String(error?.code||'UNKNOWN').trim().toUpperCase();
    return raw.replace(/[^A-Z0-9_]/g,'').slice(0,32)||'UNKNOWN';
}
function linkTaskMissingColumnFromError(error){
    const text=String(error?.message||error||'');
    const patterns=[
        /could not find the ['"]([^'"]+)['"] column/i,
        /column\s+["']?link_task_attempts["']?\.["']?([a-zA-Z0-9_]+)["']?\s+does not exist/i,
        /column\s+["']?([a-zA-Z0-9_]+)["']?\s+does not exist/i
    ];
    for(const re of patterns){
        const m=text.match(re);
        if(m?.[1] && LINK_TASK_DB_COLUMNS.includes(m[1])) return m[1];
    }
    return '';
}
function linkTaskDbSafeReason(state){
    if(state?.code==='link_task_db_access_denied'){
        return 'Hệ thống nhiệm vụ đang được hoàn tất cấu hình quyền truy cập. Vui lòng thử lại sau.';
    }
    return 'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.';
}
async function checkLinkTaskDatabaseReadiness({force=false}={}){
    const now=Date.now();
    if(!SUPABASE_SERVICE_ROLE_KEY){
        return {
            ready:false,tableReady:false,columnsReady:false,rpcReady:false,rewardRpcReady:false,verifyRpcReady:false,accessReady:false,
            code:'missing_service_role',tableCode:'NOT_CHECKED',columnsCode:'NOT_CHECKED',rpcCode:'NOT_CHECKED',rewardRpcCode:'NOT_CHECKED',verifyRpcCode:'NOT_CHECKED',
            missingColumn:'',checkedAt:now,safeReason:'Hệ thống nhiệm vụ đang được cấu hình. Vui lòng thử lại sau.'
        };
    }

    if(!force && linkTaskDbReadinessCache){
        const ttl=linkTaskDbReadinessCache.ready?LINK_TASK_DB_READY_TTL_MS:LINK_TASK_DB_NOT_READY_TTL_MS;
        if(now-Number(linkTaskDbReadinessCache.checkedAt||0)<ttl) return linkTaskDbReadinessCache;
    }
    if(linkTaskDbReadinessPromise) return linkTaskDbReadinessPromise;

    linkTaskDbReadinessPromise=(async()=>{
        const base={
            ready:false,tableReady:false,columnsReady:false,rpcReady:false,rewardRpcReady:false,verifyRpcReady:false,accessReady:false,
            code:'link_task_db_not_ready',tableCode:'NOT_CHECKED',columnsCode:'NOT_CHECKED',rpcCode:'NOT_CHECKED',
            rewardRpcCode:'NOT_CHECKED',verifyRpcCode:'NOT_CHECKED',
            missingColumn:'',checkedAt:Date.now(),safeReason:'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'
        };
        try{
            const db=linkTaskDb();

            // Probe nhẹ chỉ cột id để phân biệt table/access với lỗi thiếu cột nghiệp vụ.
            const tableProbe=await db.from('link_task_attempts').select('id').limit(1);
            if(tableProbe.error){
                const state=linkTaskDbErrorState(tableProbe.error);
                const code=linkTaskDbDiagnosticCode(tableProbe.error);
                const result={
                    ...base,
                    tableCode:code,
                    columnsCode:'NOT_CHECKED',
                    rpcCode:'NOT_CHECKED',
                    code:state?.code||'database_error',
                    safeReason:state?.message||'Tạm thời chưa kiểm tra được dữ liệu nhiệm vụ. Vui lòng thử lại sau.'
                };
                linkTaskDbReadinessCache=result;
                return result;
            }

            base.tableReady=true;
            base.tableCode='OK';

            // Columns và 2 RPC độc lập sau khi table đã đọc được -> chạy song song để giảm latency.
            const [columnsProbe,rewardRpcProbe,verifyRpcProbe]=await Promise.all([
                db.from('link_task_attempts').select(LINK_TASK_DB_COLUMNS.join(',')).limit(1),
                db.rpc('link_task_reward_atomic',{
                    p_nonce:'__linkdb_probe__',
                    p_user_id:'__diagnostic__',
                    p_quota_type:'rolling24h',
                    p_window_start:new Date(0).toISOString(),
                    p_day_key:vietnamDayKey(),
                    p_max_ip:0,
                    p_max_device:0,
                    p_max_device_ip:0
                }),
                db.rpc('link_task_verify_code_atomic',{
                    p_nonce:'__linkdb_probe__',
                    p_user_id:'__diagnostic__',
                    p_code_valid:false,
                    p_quota_type:'rolling24h',
                    p_window_start:new Date(0).toISOString(),
                    p_day_key:vietnamDayKey(),
                    p_max_ip:0,
                    p_max_device:0,
                    p_max_device_ip:0
                })
            ]);

            let columnsReady=true;
            let columnsCode='OK';
            let missingColumn='';
            let columnsState=null;
            if(columnsProbe.error){
                columnsReady=false;
                columnsCode=linkTaskDbDiagnosticCode(columnsProbe.error);
                missingColumn=linkTaskMissingColumnFromError(columnsProbe.error);
                columnsState=linkTaskDbErrorState(columnsProbe.error);
            }

            const inspectRpcProbe=(probe)=>{
                if(probe.error){
                    return {ready:false,code:linkTaskDbDiagnosticCode(probe.error),state:linkTaskDbErrorState(probe.error)};
                }
                const rpcResult=Array.isArray(probe.data)?probe.data[0]:probe.data;
                if(rpcResult && rpcResult.ok===false && String(rpcResult.code||'')==='not_found'){
                    return {ready:true,code:'OK',state:null};
                }
                return {ready:false,code:'UNEXPECTED_RESULT',state:null};
            };
            const rewardRpc=inspectRpcProbe(rewardRpcProbe);
            const verifyRpc=inspectRpcProbe(verifyRpcProbe);
            const rpcReady=rewardRpc.ready && verifyRpc.ready;
            const rpcCode=rewardRpc.ready ? (verifyRpc.ready ? 'OK' : verifyRpc.code) : rewardRpc.code;

            // tableProbe bằng service-role đã đọc được => quyền truy cập server-side hoạt động.
            // RPC/columns là readiness riêng, không đánh đồng thành lỗi RLS.
            const accessReady=base.tableReady;
            const ready=base.tableReady && columnsReady && rpcReady && accessReady;
            const state=columnsState||rewardRpc.state||verifyRpc.state;
            const result={
                ...base,
                ready,
                tableReady:true,
                columnsReady,
                rpcReady,
                rewardRpcReady:rewardRpc.ready,
                verifyRpcReady:verifyRpc.ready,
                accessReady,
                tableCode:'OK',
                columnsCode,
                rpcCode,
                rewardRpcCode:rewardRpc.code,
                verifyRpcCode:verifyRpc.code,
                missingColumn,
                code:ready?'ready':(state?.code||'link_task_db_not_ready'),
                checkedAt:Date.now(),
                safeReason:ready?'':linkTaskDbSafeReason(state||{})
            };
            linkTaskDbReadinessCache=result;
            return result;
        }catch(error){
            const state=linkTaskDbErrorState(error);
            const result={
                ...base,
                code:state?.code||'database_error',
                tableCode:linkTaskDbDiagnosticCode(error),
                safeReason:state?.message||'Tạm thời chưa kiểm tra được dữ liệu nhiệm vụ. Vui lòng thử lại sau.'
            };
            linkTaskDbReadinessCache=result;
            return result;
        }
    })();

    try{
        return await linkTaskDbReadinessPromise;
    }finally{
        linkTaskDbReadinessPromise=null;
    }
}
function linkTaskRuleText(cfg){
    const suffix=cfg.quotaType==='rolling24h'?'/24H':'/ngày';
    const out=[];
    if(cfg.maxPerIp>0) out.push(`${cfg.maxPerIp} lần/IP${suffix}`);
    if(cfg.maxPerDevice>0) out.push(`${cfg.maxPerDevice} lần/thiết bị${suffix}`);
    if(cfg.maxPerDeviceIp>0) out.push(`${cfg.maxPerDeviceIp} lần/thiết bị/IP${suffix}`);
    return out.join(' • ');
}
function linkTaskPublicConfig(cfg,remaining=null,latest=null,runtime={}){
    const state=runtime.forcedState || linkTaskUnavailableState(cfg,runtime);
    const rawStatus=String(latest?.status||'idle');
    const expiresAt=latest?.expires_at||null;
    const expiredActive=['created','shortened','landed'].includes(rawStatus) && expiresAt && new Date(expiresAt).getTime()<=Date.now();
    const status=expiredActive?'expired':rawStatus;
    const shortUrl=(status==='created'||status==='shortened')?String(latest?.short_url||''):'';
    return {
        id:cfg.key,name:cfg.provider,rewardOrders:cfg.rewardOrders,quotaType:cfg.quotaType,
        maxPerIp:cfg.maxPerIp,maxPerDevice:cfg.maxPerDevice,maxPerDeviceIp:cfg.maxPerDeviceIp||0,
        rule:linkTaskRuleText(cfg),
        available:!state.message,unavailableCode:state.code||'',unavailableReason:state.message||'',
        remaining:remaining===null?(cfg.maxPerIp||cfg.maxPerDevice||cfg.maxPerDeviceIp||0):Math.max(0,Number(remaining||0)),
        status,shortUrl,expiresAt,rewardedAt:latest?.rewarded_at||null
    };
}
function safeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function linkTaskVerificationCode(attempt){
    if(!attempt||!IP_HASH_SECRET) return '';
    const digest=crypto.createHmac('sha256',IP_HASH_SECRET)
        .update(`link-code-v1|${String(attempt.nonce||'')}|${String(attempt.user_id||'')}|${String(attempt.task_id||'')}`)
        .digest();
    return String(digest.readUInt32BE(0)%1000000).padStart(6,'0');
}
function timingSafeEqualDigits(a,b){
    const left=Buffer.from(String(a||''),'utf8'),right=Buffer.from(String(b||''),'utf8');
    return left.length===right.length && left.length>0 && crypto.timingSafeEqual(left,right);
}
async function fetchWithTimeoutServer(url,options={},timeoutMs=8000){
    const controller=new AbortController(); const timer=setTimeout(()=>controller.abort(),timeoutMs);
    try{return await fetch(url,{...options,signal:controller.signal});}finally{clearTimeout(timer);}
}
async function fetchProviderWithRetry(url,options={},timeoutMs=8000,retries=1){
    let lastError=null;
    for(let attempt=0;attempt<=Math.max(0,retries);attempt++){
        try{
            const response=await fetchWithTimeoutServer(url,options,timeoutMs);
            const retryable=[429,500,502,503,504].includes(response.status);
            if(!retryable||attempt>=retries)return response;
            const retryAfter=Math.min(2500,Math.max(350,Number(response.headers.get('retry-after')||0)*1000||500*(attempt+1)));
            try{await response.body?.cancel();}catch(_){}
            await new Promise(r=>setTimeout(r,retryAfter));
        }catch(e){
            lastError=e;if(attempt>=retries)throw e;
            await new Promise(r=>setTimeout(r,450*(attempt+1)));
        }
    }
    throw lastError||new Error('Provider request failed.');
}
function validateShortUrl(raw,hosts){
    try{const u=new URL(String(raw||'').trim());const h=u.hostname.toLowerCase();return u.protocol==='https:'&&hosts.some(x=>h===x||h.endsWith('.'+x))?u.toString():'';}catch(_){return '';}
}
function safeProviderDiagnostic(error){
    let text=String(error?.message||error||'provider_error');
    for(const secret of [SHRINKPE_API_TOKEN,CUTY_API_TOKEN,BBMKTS_API_TOKEN,LAYMA_API_TOKEN,SITE2S_API_TOKEN,UPTOLINK_API_TOKEN]){
        if(secret)text=text.split(secret).join('[REDACTED]');
    }
    text=text.replace(/https?:\/\/[^\s]+/gi,'[URL_REDACTED]').replace(/[\r\n\t]+/g,' ').trim();
    return text.slice(0,180)||'provider_error';
}
async function readProviderJson(response, providerName) {
    const raw = await response.text();
    if (!raw) throw new Error(`${providerName} trả response rỗng.`);
    try { return JSON.parse(raw); }
    catch (_) { throw new Error(`${providerName} trả JSON không hợp lệ.`); }
}
async function createProviderShortUrl(cfg,destination,nonce){
    if(cfg.key==='shrinkpe'){
        const buildUrl=(format)=>{
            const u=new URL('https://shrink.pe/api');
            u.searchParams.set('api',SHRINKPE_API_TOKEN);
            u.searchParams.set('url',destination);
            u.searchParams.set('format',format);
            return u;
        };

        // Lần 1: JSON. Body chỉ đọc đúng một lần rồi tự parse từ raw text.
        const jsonResponse=await fetchProviderWithRetry(buildUrl('json'),{headers:{accept:'application/json,text/plain;q=0.8'}},8000,1);
        const jsonRaw=await jsonResponse.text();
        if(!jsonResponse.ok) throw new Error(`SHRINK.PE HTTP ${jsonResponse.status}`);
        if(!jsonRaw.trim()) throw new Error('SHRINK.PE empty response');

        let jsonData=null;
        try{jsonData=JSON.parse(jsonRaw);}catch(_){jsonData=null;}
        if(jsonData && String(jsonData?.status||'').toLowerCase()==='success'){
            const shortUrl=validateShortUrl(jsonData?.shortenedUrl,['shrink.pe']);
            if(shortUrl)return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
        }

        // Lần 2 duy nhất theo format=text: dùng khi JSON 200 nhưng parse/field/link không hợp lệ.
        const textResponse=await fetchProviderWithRetry(buildUrl('text'),{headers:{accept:'text/plain'}},8000,0);
        const textRaw=(await textResponse.text()).trim();
        if(!textResponse.ok) throw new Error(`SHRINK.PE text HTTP ${textResponse.status}`);
        if(!textRaw) throw new Error('SHRINK.PE text empty response');
        const shortUrl=validateShortUrl(textRaw,['shrink.pe']);
        if(!shortUrl) throw new Error(jsonData ? 'SHRINK.PE invalid short URL' : 'SHRINK.PE invalid JSON/text URL');
        return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
    }
    if(cfg.key==='cuty'){
        const u=new URL('https://cuty.io/api');
        u.searchParams.set('api',CUTY_API_TOKEN);
        u.searchParams.set('url',destination);
        u.searchParams.set('format','json');
        const r=await fetchProviderWithRetry(u,{headers:{accept:'application/json'}},8000,1);
        const data=await readProviderJson(r,'CUTY');
        if(!r.ok||String(data?.status||'').toLowerCase()!=='success')throw new Error(`CUTY HTTP ${r.status}`);
        const shortUrl=validateShortUrl(data?.shortenedUrl,['cuty.io']);
        if(!shortUrl)throw new Error('CUTY trả link không hợp lệ.');
        return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
    }
    if(cfg.key==='bbmkts'){
        const u=new URL('https://bbmkts.com/dapi');
        u.searchParams.set('token',BBMKTS_API_TOKEN);
        u.searchParams.set('longurl',destination);
        u.searchParams.set('format','json');
        const r=await fetchProviderWithRetry(u,{headers:{accept:'application/json'}},8000,1);
        const data=await readProviderJson(r,'BBMKTS');
        if(!r.ok||String(data?.status||'').toLowerCase()!=='success')throw new Error(`BBMKTS HTTP ${r.status}`);
        const shortUrl=validateShortUrl(data?.bbmktsUrl,['bbmkts.com']);
        if(!shortUrl)throw new Error('BBMKTS trả link không hợp lệ.');
        return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
    }
    if(cfg.key==='layma'){
        const fallbackUrl=new URL(`/api/link-task/provider-fallback/${encodeURIComponent(nonce)}`,WEB_APP_URL).toString();
        const buildUrl=(format)=>{
            const u=new URL('https://api.layma.net/api/admin/shortlink/quicklink');
            u.searchParams.set('tokenUser',LAYMA_API_TOKEN);
            u.searchParams.set('format',format);
            u.searchParams.set('url',destination);
            // TUYỆT ĐỐI không dùng reward landing làm link dự phòng: no-campaign phải fail closed.
            u.searchParams.set('link_du_phong',fallbackUrl);
            return u;
        };
        const r=await fetchProviderWithRetry(buildUrl('json'),{headers:{accept:'application/json,text/plain;q=0.8'}},8000,1);
        const raw=await r.text();
        if(!r.ok)throw new Error(`LAYMA HTTP ${r.status}`);
        let data=null;
        try{data=raw?JSON.parse(raw):null;}catch(_){data=null;}
        if(data?.success===true){
            const shortUrl=validateShortUrl(data?.html,['layma.net']);
            if(shortUrl)return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
        }
        const textResponse=await fetchProviderWithRetry(buildUrl('text'),{headers:{accept:'text/plain'}},8000,0);
        const textRaw=(await textResponse.text()).trim();
        if(!textResponse.ok)throw new Error(`LAYMA text HTTP ${textResponse.status}`);
        if(!textRaw)throw new Error('LAYMA text empty response');
        const shortUrl=validateShortUrl(textRaw,['layma.net']);
        if(!shortUrl)throw new Error(data?'LAYMA invalid short URL':'LAYMA invalid JSON/text URL');
        return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
    }
    if(cfg.key==='uptolink_step2'||cfg.key==='uptolink_step3'||cfg.key==='uptolink_step4'){
        const buildUrl=(format)=>{
            const u=new URL('https://octolink.vip/api');
            u.searchParams.set('api',UPTOLINK_API_TOKEN);
            u.searchParams.set('url',destination);
            u.searchParams.set('format',format);
            u.searchParams.set('type',String(cfg.uptolinkType));
            return u;
        };
        const r=await fetchProviderWithRetry(buildUrl('json'),{headers:{accept:'application/json,text/plain;q=0.8'}},8000,1);
        const raw=await r.text();
        if(!r.ok)throw new Error(`UPTOLINK HTTP ${r.status}`);
        let data=null;
        try{data=raw?JSON.parse(raw):null;}catch(_){data=null;}
        if(String(data?.status||'').toLowerCase()==='success'){
            const shortUrl=validateShortUrl(data?.shortenedUrl,['octolink.vip']);
            if(shortUrl)return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
        }
        const textResponse=await fetchProviderWithRetry(buildUrl('text'),{headers:{accept:'text/plain'}},8000,0);
        const textRaw=(await textResponse.text()).trim();
        if(!textResponse.ok)throw new Error(`UPTOLINK text HTTP ${textResponse.status}`);
        if(!textRaw)throw new Error('UPTOLINK text empty response');
        const shortUrl=validateShortUrl(textRaw,['octolink.vip']);
        if(!shortUrl)throw new Error(data?'UPTOLINK invalid short URL':'UPTOLINK invalid JSON/text URL');
        return {shortUrl,slug:new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||''};
    }
    if(cfg.key==='site2s'){
        const u=new URL('https://site2s.com/api');
        u.searchParams.set('api',SITE2S_API_TOKEN);
        u.searchParams.set('url',destination);
        u.searchParams.set('format','json');
        u.searchParams.set('type','1');
        const r=await fetchProviderWithRetry(u,{headers:{accept:'application/json'}},8000,1);
        const data=await readProviderJson(r,'SITE2S');
        if(!r.ok||String(data?.status||'').toLowerCase()!=='success')throw new Error(`SITE2S HTTP ${r.status}`);
        const shortUrl=validateShortUrl(data?.shortenedUrl,['site2s.com']);
        if(!shortUrl)throw new Error('SITE2S trả link không hợp lệ.');
        const slug=new URL(shortUrl).pathname.split('/').filter(Boolean).pop()||'';
        let baseline=null;
        if(slug){
            try{
                const info=await fetchWithTimeoutServer(`https://site2s.com/${encodeURIComponent(slug)}/info/json`,{headers:{accept:'application/json'}},5000);
                const j=await info.json().catch(()=>({}));
                if(info.ok&&Number.isFinite(Number(j?.view)))baseline=Number(j.view);
            }catch(_){}
        }
        return {shortUrl,slug,baseline};
    }
    throw new Error('Provider chưa được hỗ trợ.');
}
async function linkTaskCountFor(cfg,{ipHash='',deviceHash='',userId='',resetAt=null}={}){
    const db=linkTaskDb();
    let effectiveResetAt=resetAt;
    if(effectiveResetAt===null && userId){
        const reset=await readLinkTaskQuotaReset(userId);
        effectiveResetAt=reset?.resetAt||'';
    }
    const apply=q=>cfg.quotaType==='vietnamDay'?q.eq('day_key',vietnamDayKey()):q.gte('rewarded_at',new Date(Date.now()-LINK_TASK_ROLLING_MS).toISOString());
    const deviceIpHash=ipHash&&deviceHash?hashNetworkValue(`${deviceHash}:${ipHash}`,'device-ip'):'';
    const countQuery=async(field,value)=>{
        if(!value)return 0;
        let q=db.from('link_task_attempts').select('id',{count:'exact',head:true})
            .eq('task_id',cfg.taskId).eq('status','rewarded').eq(field,value);
        q=apply(q);
        // Bỏ CHỈ reward cũ của chính user trước reset; tài khoản khác chung IP/device vẫn được tính.
        if(userId&&effectiveResetAt)q=q.or(`user_id.neq.${String(userId)},rewarded_at.gte.${String(effectiveResetAt)}`);
        const {count,error}=await q;
        if(error)throw error;
        return Number(count||0);
    };
    const [ipCount,deviceCount,deviceIpCount]=await Promise.all([
        cfg.maxPerIp>0?countQuery('landing_ip_hash',ipHash):Promise.resolve(0),
        cfg.maxPerDevice>0?countQuery('device_hash',deviceHash):Promise.resolve(0),
        cfg.maxPerDeviceIp>0?countQuery('device_ip_hash',deviceIpHash):Promise.resolve(0)
    ]);
    const a=cfg.maxPerIp>0?Math.max(0,cfg.maxPerIp-ipCount):Number.MAX_SAFE_INTEGER;
    const b=cfg.maxPerDevice>0?Math.max(0,cfg.maxPerDevice-deviceCount):Number.MAX_SAFE_INTEGER;
    const c=cfg.maxPerDeviceIp>0?Math.max(0,cfg.maxPerDeviceIp-deviceIpCount):Number.MAX_SAFE_INTEGER;
    return {ipCount,deviceCount,deviceIpCount,remaining:Math.min(a,b,c),resetAt:effectiveResetAt||null};
}
const LINK_TASK_ACTIVE_STATUSES = Object.freeze(['created','shortened','landed']);
function linkTaskAttemptIsActive(attempt){
    return !!attempt && LINK_TASK_ACTIVE_STATUSES.includes(String(attempt.status||''));
}
function linkTaskAttemptIsExpired(attempt,nowMs=Date.now()){
    if(!attempt)return true;
    const expiresMs=Date.parse(String(attempt.expires_at||''));
    return !Number.isFinite(expiresMs) || expiresMs<=nowMs;
}
async function normalizeLinkTaskAttemptExpiry(attempt,db=linkTaskDb()){
    if(!attempt||!linkTaskAttemptIsActive(attempt)||!linkTaskAttemptIsExpired(attempt))return attempt;
    const {data:expired,error}=await db.from('link_task_attempts')
        .update({status:'expired'})
        .eq('id',attempt.id)
        .in('status',LINK_TASK_ACTIVE_STATUSES)
        .select('*').maybeSingle();
    if(error)throw error;
    if(expired)return expired;
    const {data:fresh,error:freshError}=await db.from('link_task_attempts').select('*').eq('id',attempt.id).maybeSingle();
    if(freshError)throw freshError;
    return fresh||null;
}
async function getActiveLinkTaskAttempt(userId,taskId){
    const db=linkTaskDb();
    const {data,error}=await db.from('link_task_attempts').select('*')
        .eq('user_id',String(userId)).eq('task_id',taskId)
        .in('status',LINK_TASK_ACTIVE_STATUSES)
        .order('created_at',{ascending:false}).limit(1).maybeSingle();
    if(error)throw error;
    if(!data)return null;
    const normalized=await normalizeLinkTaskAttemptExpiry(data,db);
    return linkTaskAttemptIsActive(normalized)?normalized:null;
}
function linkTaskAttemptClientPayload(cfg,attempt,{reused=false,processing=false}={}){
    const status=String(attempt?.status||'idle');
    const shortUrl=(status==='created'||status==='shortened')?String(attempt?.short_url||''):'';
    const creating=status==='created'&&!shortUrl;
    return {
        success:true,reused:!!reused,processing:!!processing,creating,
        code:creating?'creating':'',
        taskId:cfg.taskId,status,shortUrl,expiresAt:attempt?.expires_at||null,
        task:linkTaskPublicConfig(cfg,null,attempt)
    };
}
async function createFreshLinkTaskAttempt({userId,cfg,ipHash,deviceHash}){
    const quotaReset=await readLinkTaskQuotaReset(userId).catch(()=>null);
    const quota=await linkTaskCountFor(cfg,{ipHash,deviceHash,userId,resetAt:quotaReset?.resetAt||''});
    if(quota.remaining<=0){
        return {ok:false,httpStatus:429,limitReached:true,code:'quota_reached',error:'Bạn đã hết lượt của nhiệm vụ này theo IP/thiết bị.'};
    }

    const nonce=crypto.randomBytes(18).toString('base64url');
    const now=new Date();
    const expiresAt=new Date(now.getTime()+LINK_TASK_TTL_MS).toISOString();
    const destination=new URL(`/api/link-task/landing/${encodeURIComponent(nonce)}`,WEB_APP_URL).toString();
    const db=linkTaskDb();
    const row={
        nonce,user_id:userId,provider:cfg.provider,task_id:cfg.taskId,status:'created',
        reward_orders:cfg.rewardOrders,day_key:vietnamDayKey(),
        issued_ip_hash:ipHash,landing_ip_hash:null,device_hash:deviceHash,device_ip_hash:null,
        country_code:null,is_vpn:false,
        created_at:now.toISOString(),expires_at:expiresAt,
        metadata:{quotaType:cfg.quotaType,maxPerIp:cfg.maxPerIp,maxPerDevice:cfg.maxPerDevice,maxPerDeviceIp:cfg.maxPerDeviceIp||0}
    };
    const {data:inserted,error:insertError}=await db.from('link_task_attempts').insert(row).select('*').single();
    if(insertError){
        if(insertError.code==='23505'){
            const existing=await getActiveLinkTaskAttempt(userId,cfg.taskId);
            if(existing)return {ok:true,attempt:existing,reused:true};
        }
        throw insertError;
    }

    try{
        const made=await createProviderShortUrl(cfg,destination,nonce);
        const {data:updated,error:updateError}=await db.from('link_task_attempts')
            .update({
                status:'shortened',
                short_url:made.shortUrl,
                provider_slug:made.slug||null,
                provider_view_baseline:Number.isFinite(Number(made.baseline))?Number(made.baseline):null
            })
            .eq('id',inserted.id)
            .eq('status','created')
            .gt('expires_at',new Date().toISOString())
            .select('*').maybeSingle();
        if(updateError)throw updateError;
        if(updated)return {ok:true,attempt:updated,reused:false};

        const {data:fresh,error:freshError}=await db.from('link_task_attempts').select('*').eq('id',inserted.id).maybeSingle();
        if(freshError)throw freshError;
        const normalized=await normalizeLinkTaskAttemptExpiry(fresh,db);
        if(normalized?.status==='expired'){
            return {ok:false,httpStatus:410,code:'expired',error:'Nhiệm vụ đã hết thời gian 10 phút. Vui lòng nhận nhiệm vụ mới.'};
        }
        if(normalized?.status==='cancelled'){
            return {ok:false,httpStatus:409,code:'cancelled',error:'Nhiệm vụ này đã bị hủy. Vui lòng nhận nhiệm vụ mới.'};
        }
        if(linkTaskAttemptIsActive(normalized))return {ok:true,attempt:normalized,reused:true};
        return {ok:false,httpStatus:409,code:'state_changed',error:'Trạng thái nhiệm vụ đã thay đổi. Vui lòng tải lại nhiệm vụ.'};
    }catch(pe){
        const dbState=linkTaskDbErrorState(pe);
        if(dbState)linkTaskDbReadinessCache=null;
        try{
            await db.from('link_task_attempts').update({
                status:'cancelled',
                metadata:{...row.metadata,providerError:safeProviderDiagnostic(pe)}
            }).eq('id',inserted.id).eq('status','created');
        }catch(_){}
        console.error(`Link provider ${cfg.key}:`,safeProviderDiagnostic(pe));
        if(dbState)return {ok:false,httpStatus:503,providerUnavailable:true,code:dbState.code,error:dbState.message};
        return {ok:false,httpStatus:503,providerUnavailable:true,code:'provider_error',error:'Nhà cung cấp link đang tạm thời bận. Vui lòng thử lại sau.'};
    }
}
async function checkGlobalMiniAppNetworkAccess(req){
    const ip=requestIp(req);
    if(!ip)return {ok:true,ip:'',risk:null,networkVerificationAvailable:false,networkVerificationReason:'IP_UNAVAILABLE'};
    const risk=await checkIpRisk(ip);
    if(!risk.available)return {ok:true,ip,risk:null,networkVerificationAvailable:false,networkVerificationReason:risk.reason||'IP_INTELLIGENCE_TEMPORARILY_UNAVAILABLE'};
    if(networkRiskBlocked(risk))return {ok:false,status:403,vpnBlocked:true,error:'Phát hiện VPN/Proxy/Tor/Datacenter. Vui lòng tắt VPN/Proxy để tiếp tục.'};
    return {ok:true,ip,risk,networkVerificationAvailable:true,networkVerificationReason:null};
}
app.post('/api/access-check',async(req,res)=>{
    const userId=String(req.body?.userId||'');
    if(!assertTelegramUser(req,userId))return res.status(401).json({success:false,allowed:false,authBlocked:true,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res))return;
    try{
        const current=await readUserRow(userId);
        if(current.error)throw current.error;
        if(current.data?.isBanned)return res.status(403).json({success:false,allowed:false,accountBlocked:true,error:'Tài khoản hiện đang bị khóa.'});
        const n=await checkGlobalMiniAppNetworkAccess(req);
        if(!n.ok)return res.status(n.status).json({success:false,allowed:false,vpnBlocked:true,error:n.error});
        if(current.data&&n.ip&&String(current.data.ip||'')!==n.ip)await saveUserFields(userId,{ip:n.ip});
        return res.json({success:true,allowed:true,networkVerificationAvailable:n.networkVerificationAvailable,networkVerificationReason:n.networkVerificationReason,countryCode:n.risk?.countryCode||''});
    }catch(e){
        console.error('Access check failed:',e?.message||e);
        return res.status(503).json({success:false,allowed:false,serverUnavailable:true,error:'Máy chủ tạm thời chưa thể xác minh phiên truy cập. Vui lòng thử lại.'});
    }
});
app.get('/api/link-task/status/:id',async(req,res)=>{
    const userId=String(req.params.id||'');
    if(!assertTelegramUser(req,userId))return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res))return;
    try{
        const ip=requestIp(req);
        const deviceId=requestDeviceId(req);
        if(!deviceId)return res.status(400).json({success:false,error:'Không xác định được thiết bị. Vui lòng mở lại Mini App trong Telegram.'});

        const deviceHash=IP_HASH_SECRET?hashNetworkValue(deviceId,'device'):'';
        const ipHash=(IP_HASH_SECRET&&ip)?hashNetworkValue(ip,'ip'):'';
        const userPromise=readUserRow(userId);
        const quotaResetPromise=SUPABASE_SERVICE_ROLE_KEY?readLinkTaskQuotaReset(userId).catch(()=>null):Promise.resolve(null);

        // Database/RPC là dependency chung: probe MỘT LẦN, có cache 30-60s.
        // Không để 8 provider cùng query schema lỗi và spam log.
        const dbReadiness=(SUPABASE_SERVICE_ROLE_KEY&&IP_HASH_SECRET)
            ? await checkLinkTaskDatabaseReadiness()
            : null;

        const items=await Promise.all(Object.values(LINK_TASK_CONFIG).map(async cfg=>{
            const runtime={ipAvailable:!!ip};
            const unavailable=linkTaskUnavailableState(cfg,runtime);
            if(unavailable.message){
                return linkTaskPublicConfig(cfg,null,null,{...runtime,forcedState:unavailable});
            }
            if(dbReadiness && !dbReadiness.ready){
                return linkTaskPublicConfig(cfg,null,null,{
                    ...runtime,
                    forcedState:{
                        code:dbReadiness.code||'link_task_db_not_ready',
                        message:dbReadiness.safeReason||'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'
                    }
                });
            }
            try{
                const db=linkTaskDb();
                const quotaReset=await quotaResetPromise;
                const [quota,latestResult]=await Promise.all([
                    linkTaskCountFor(cfg,{ipHash,deviceHash,userId,resetAt:quotaReset?.resetAt||''}),
                    db.from('link_task_attempts')
                        .select('id,status,created_at,expires_at,rewarded_at,short_url')
                        .eq('user_id',userId).eq('task_id',cfg.taskId)
                        .order('created_at',{ascending:false}).limit(1).maybeSingle()
                ]);
                if(latestResult.error)throw latestResult.error;
                const latest=await normalizeLinkTaskAttemptExpiry(latestResult.data||null,db);
                return linkTaskPublicConfig(cfg,quota.remaining,latest,runtime);
            }catch(e){
                console.error(`Link task status ${cfg.key}:`,linkTaskDbDiagnosticCode(e));
                const dbState=linkTaskDbErrorState(e);
                if(dbState) linkTaskDbReadinessCache=null;
                return linkTaskPublicConfig(cfg,null,null,{
                    ...runtime,
                    forcedState:dbState||{code:'database_error',message:'Tạm thời chưa tải được trạng thái của nhiệm vụ này. Vui lòng thử lại sau.'}
                });
            }
        }));

        const {data:user}=await userPromise;
        res.set('Cache-Control','no-store');
        return res.json({
            success:true,tasks:items,
            orders:Number(user?.orders||0),coins:Number(user?.coins||0),spins:Number(user?.spins||0),
            walletUpdatedAt:user?.walletUpdatedAt||null
        });
    }catch(e){
        console.error('Link task status:',e?.message||e);
        return res.status(500).json({success:false,error:'Không đọc được trạng thái nhiệm vụ vượt link. Vui lòng thử lại sau.'});
    }
});
app.post('/api/link-task/start',async(req,res)=>{
    const userId=String(req.body?.userId||''),taskId=String(req.body?.taskId||'');
    if(!assertTelegramUser(req,userId))return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res))return;

    const cfg=LINK_TASK_CONFIG[taskId];
    if(!cfg)return res.status(400).json({success:false,code:'provider_unsupported',error:'Nhiệm vụ vượt link không hợp lệ.'});

    const ip=requestIp(req);
    const deviceId=requestDeviceId(req);
    if(!deviceId)return res.status(400).json({success:false,code:'device_unavailable',error:'Không xác định được thiết bị. Vui lòng mở lại Mini App trong Telegram.'});

    const runtime={ipAvailable:!!ip};
    const unavailable=linkTaskUnavailableState(cfg,runtime);
    if(unavailable.message){
        return res.status(503).json({success:false,providerUnavailable:true,code:unavailable.code,error:unavailable.message});
    }
    if(linkTaskNeedsRequestIp(cfg)&&!ip){
        return res.status(503).json({success:false,providerUnavailable:true,code:'ip_unavailable',error:'Tạm thời chưa xác định được IP kết nối cho nhiệm vụ này.'});
    }

    const ipHash=ip?hashNetworkValue(ip,'ip'):'';
    const deviceHash=hashNetworkValue(deviceId,'device');
    if((linkTaskNeedsRequestIp(cfg)&&!ipHash)||!deviceHash){
        return res.status(503).json({success:false,providerUnavailable:true,code:'hash_unavailable',error:'Hệ thống xác minh lượt nhiệm vụ đang được cấu hình. Vui lòng thử lại sau.'});
    }

    const dbReadiness=await checkLinkTaskDatabaseReadiness();
    if(!dbReadiness.ready){
        return res.status(503).json({
            success:false,providerUnavailable:true,
            code:dbReadiness.code||'link_task_db_not_ready',
            error:dbReadiness.safeReason||'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'
        });
    }

    try{
        const beforeLock=await getActiveLinkTaskAttempt(userId,cfg.taskId);
        if(beforeLock){
            const payload=linkTaskAttemptClientPayload(cfg,beforeLock,{reused:true});
            return res.status(payload.creating?202:200).json(payload);
        }

        const release=await acquirePersistentLeaseLock(
            persistentEventKey('link-task-start-lock',`${userId}:${taskId}`),
            60 * 1000
        );
        if(!release){
            const raced=await getActiveLinkTaskAttempt(userId,cfg.taskId);
            if(raced){
                const payload=linkTaskAttemptClientPayload(cfg,raced,{reused:true,processing:true});
                return res.status(payload.creating?202:200).json(payload);
            }
            return res.status(202).json({
                success:true,processing:true,creating:true,code:'processing',taskId,
                status:'creating',shortUrl:'',expiresAt:null,
                message:'Hệ thống đang tạo nhiệm vụ. Vui lòng chờ một chút.'
            });
        }

        try{
            const active=await getActiveLinkTaskAttempt(userId,cfg.taskId);
            if(active){
                const payload=linkTaskAttemptClientPayload(cfg,active,{reused:true});
                return res.status(payload.creating?202:200).json(payload);
            }

            const created=await createFreshLinkTaskAttempt({userId,cfg,ipHash,deviceHash});
            if(!created.ok){
                return res.status(created.httpStatus||503).json({
                    success:false,
                    providerUnavailable:!!created.providerUnavailable,
                    limitReached:!!created.limitReached,
                    code:created.code||'link_task_error',
                    error:created.error||'Không thể tạo nhiệm vụ vượt link. Vui lòng thử lại sau.'
                });
            }
            const payload=linkTaskAttemptClientPayload(cfg,created.attempt,{reused:!!created.reused});
            return res.status(payload.creating?202:200).json(payload);
        }finally{
            try{await release();}catch(_){}
        }
    }catch(e){
        console.error('Link task start:',linkTaskDbDiagnosticCode(e),e?.message||e);
        const dbState=linkTaskDbErrorState(e);
        if(dbState)linkTaskDbReadinessCache=null;
        if(dbState)return res.status(503).json({success:false,providerUnavailable:true,code:dbState.code,error:dbState.message});
        return res.status(500).json({success:false,code:'database_error',error:'Không thể tạo nhiệm vụ vượt link. Vui lòng thử lại sau.'});
    }
});

app.post('/api/link-task/change',async(req,res)=>{
    const userId=String(req.body?.userId||''),taskId=String(req.body?.taskId||'');
    if(!assertTelegramUser(req,userId))return res.status(401).json({success:false,error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res))return;

    const cfg=LINK_TASK_CONFIG[taskId];
    if(!cfg)return res.status(400).json({success:false,code:'provider_unsupported',error:'Nhiệm vụ vượt link không hợp lệ.'});

    const ip=requestIp(req);
    const deviceId=requestDeviceId(req);
    if(!deviceId)return res.status(400).json({success:false,code:'device_unavailable',error:'Không xác định được thiết bị. Vui lòng mở lại Mini App trong Telegram.'});

    const runtime={ipAvailable:!!ip};
    const unavailable=linkTaskUnavailableState(cfg,runtime);
    if(unavailable.message){
        return res.status(503).json({success:false,providerUnavailable:true,code:unavailable.code,error:unavailable.message});
    }
    if(linkTaskNeedsRequestIp(cfg)&&!ip){
        return res.status(503).json({success:false,providerUnavailable:true,code:'ip_unavailable',error:'Tạm thời chưa xác định được IP kết nối cho nhiệm vụ này.'});
    }

    const ipHash=ip?hashNetworkValue(ip,'ip'):'';
    const deviceHash=hashNetworkValue(deviceId,'device');
    if((linkTaskNeedsRequestIp(cfg)&&!ipHash)||!deviceHash){
        return res.status(503).json({success:false,providerUnavailable:true,code:'hash_unavailable',error:'Hệ thống xác minh lượt nhiệm vụ đang được cấu hình. Vui lòng thử lại sau.'});
    }

    const dbReadiness=await checkLinkTaskDatabaseReadiness();
    if(!dbReadiness.ready){
        return res.status(503).json({
            success:false,providerUnavailable:true,
            code:dbReadiness.code||'link_task_db_not_ready',
            error:dbReadiness.safeReason||'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'
        });
    }

    let release=null;
    try{
        release=await acquirePersistentLeaseLock(
            persistentEventKey('link-task-start-lock',`${userId}:${taskId}`),
            60 * 1000
        );
        if(!release){
            return res.status(202).json({
                success:true,processing:true,changing:true,creating:true,code:'processing',taskId,
                status:'changing',shortUrl:'',expiresAt:null,
                message:'Hệ thống đang đổi nhiệm vụ. Vui lòng chờ một chút.'
            });
        }

        const db=linkTaskDb();
        const active=await getActiveLinkTaskAttempt(userId,cfg.taskId);
        if(active){
            const oldMetadata=(active.metadata&&typeof active.metadata==='object'&&!Array.isArray(active.metadata))?active.metadata:{};
            const cancelledAt=new Date().toISOString();
            const {data:cancelled,error:cancelError}=await db.from('link_task_attempts')
                .update({
                    status:'cancelled',
                    metadata:{...oldMetadata,cancelledReason:'user_changed_task',cancelledAt}
                })
                .eq('id',active.id)
                .in('status',LINK_TASK_ACTIVE_STATUSES)
                .select('id,status').maybeSingle();
            if(cancelError)throw cancelError;
            if(!cancelled){
                const {data:fresh,error:freshError}=await db.from('link_task_attempts').select('status').eq('id',active.id).maybeSingle();
                if(freshError)throw freshError;
                if(fresh?.status==='rewarded'){
                    return res.status(409).json({success:false,code:'already_rewarded',error:'Nhiệm vụ vừa được xác nhận thưởng nên không thể đổi.'});
                }
            }
        }

        const created=await createFreshLinkTaskAttempt({userId,cfg,ipHash,deviceHash});
        if(!created.ok){
            return res.status(created.httpStatus||503).json({
                success:false,
                providerUnavailable:!!created.providerUnavailable,
                limitReached:!!created.limitReached,
                code:created.code||'link_task_error',
                error:created.error||'Không thể đổi nhiệm vụ vượt link. Vui lòng thử lại sau.'
            });
        }
        const payload=linkTaskAttemptClientPayload(cfg,created.attempt,{reused:!!created.reused});
        return res.status(payload.creating?202:200).json({...payload,changed:true});
    }catch(e){
        console.error('Link task change:',linkTaskDbDiagnosticCode(e),e?.message||e);
        const dbState=linkTaskDbErrorState(e);
        if(dbState)linkTaskDbReadinessCache=null;
        if(dbState)return res.status(503).json({success:false,providerUnavailable:true,code:dbState.code,error:dbState.message});
        return res.status(500).json({success:false,code:'database_error',error:'Không thể đổi nhiệm vụ vượt link. Vui lòng thử lại sau.'});
    }finally{
        if(release){try{await release();}catch(_){}}
    }
});
app.get('/api/link-task/provider-fallback/:nonce',async(req,res)=>{
    const nonce=String(req.params.nonce||'');
    try{
        const db=linkTaskDb();
        const {data:a,error}=await db.from('link_task_attempts').select('id,status,expires_at').eq('nonce',nonce).maybeSingle();
        if(error||!a)return res.status(404).send('<h2>❌ Link nhiệm vụ không hợp lệ.</h2>');
        if(['created','shortened','landed'].includes(String(a.status||'')) && (!a.expires_at || new Date(a.expires_at).getTime()<=Date.now())){
            await db.from('link_task_attempts').update({status:'expired'}).eq('id',a.id).in('status',LINK_TASK_ACTIVE_STATUSES);
        }else if(['created','shortened'].includes(String(a.status||''))){
            await db.from('link_task_attempts').update({status:'cancelled'}).eq('id',a.id).in('status',['created','shortened']);
        }
        res.set('Cache-Control','no-store, no-cache, must-revalidate');
        const mini=telegramMiniAppDeepLink('linktask');
        const botUrl=telegramBotDeepLink();
        return res.status(409).send(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nhiệm vụ tạm chưa khả dụng</title><style>body{font-family:system-ui;background:#0f172a;color:#fff;display:grid;place-items:center;min-height:100vh;margin:0;padding:20px}.c{width:min(420px,100%);box-sizing:border-box;text-align:center;background:#1e293b;border:1px solid #334155;border-radius:24px;padding:24px}.b{display:block;margin-top:12px;padding:13px;border-radius:14px;background:#2563eb;color:#fff;text-decoration:none;font-weight:800}.s{color:#cbd5e1;line-height:1.55}</style></head><body><div class="c"><div style="font-size:52px">⚠️</div><h2>NHÀ CUNG CẤP CHƯA CÓ NHIỆM VỤ</h2><p class="s">Hiện chưa có campaign phù hợp. Phiên này không được xác nhận và không có mã thưởng. Vui lòng quay lại Mini App rồi thử lại sau.</p><a class="b" href="${safeHtml(mini)}">🚀 QUAY LẠI MINI APP</a><a class="b" style="background:#0f766e" href="${safeHtml(botUrl)}">🤖 MỞ BOT TELEGRAM</a></div></body></html>`);
    }catch(e){
        console.error('Link task provider fallback:',safeProviderDiagnostic(e));
        return res.status(500).send('<h2>⚠️ Không thể xử lý nhiệm vụ lúc này.</h2>');
    }
});
app.get('/api/link-task/landing/:nonce',async(req,res)=>{
    const nonce=String(req.params.nonce||'');
    let release=null;
    try{
        const db=linkTaskDb();
        let {data:a,error}=await db.from('link_task_attempts').select('*').eq('nonce',nonce).maybeSingle();
        if(error||!a)return res.status(404).send('<h2>❌ Link xác nhận không hợp lệ.</h2>');
        const cfg=LINK_TASK_CONFIG[String(a.task_id||'')];
        if(!cfg)return res.status(400).send('<h2>❌ Nhiệm vụ không hợp lệ.</h2>');
        if(a.status==='rewarded')return res.send('<h2>ℹ️ Nhiệm vụ này đã được xác nhận trước đó.</h2>');
        if(a.status==='cancelled')return res.status(410).send('<h2>❌ Nhiệm vụ này đã bị hủy. Vui lòng nhận nhiệm vụ mới.</h2>');
        if(a.status==='expired'||linkTaskAttemptIsExpired(a)){
            if(linkTaskAttemptIsActive(a)){
                await db.from('link_task_attempts').update({status:'expired'}).eq('id',a.id).in('status',LINK_TASK_ACTIVE_STATUSES);
            }
            return res.status(410).send('<h2>⌛ NHIỆM VỤ ĐÃ HẾT HẠN</h2><p>Bạn đã vượt quá thời gian 10 phút. Vui lòng quay lại Mini App và nhận nhiệm vụ mới.</p>');
        }
        if(!linkTaskAttemptIsActive(a))return res.status(409).send('<h2>❌ Nhiệm vụ không còn ở trạng thái có thể xác nhận.</h2>');

        release=await acquirePersistentLeaseLock(
            persistentEventKey('link-task-start-lock',`${String(a.user_id)}:${String(a.task_id)}`),
            60 * 1000
        );
        if(!release){
            const {data:fresh,error:freshError}=await db.from('link_task_attempts').select('status,expires_at').eq('id',a.id).maybeSingle();
            if(freshError)throw freshError;
            if(fresh?.status==='cancelled')return res.status(410).send('<h2>❌ Nhiệm vụ này đã bị hủy. Vui lòng nhận nhiệm vụ mới.</h2>');
            if(fresh?.status==='expired'||!fresh?.expires_at||new Date(fresh.expires_at).getTime()<=Date.now()){
                return res.status(410).send('<h2>⌛ NHIỆM VỤ ĐÃ HẾT HẠN</h2><p>Bạn đã vượt quá thời gian 10 phút. Vui lòng quay lại Mini App và nhận nhiệm vụ mới.</p>');
            }
            return res.status(409).send('<h2>⏳ Nhiệm vụ đang được cập nhật. Vui lòng thử lại sau vài giây.</h2>');
        }

        ({data:a,error}=await db.from('link_task_attempts').select('*').eq('nonce',nonce).maybeSingle());
        if(error||!a)return res.status(404).send('<h2>❌ Link xác nhận không hợp lệ.</h2>');
        if(a.status==='rewarded')return res.send('<h2>ℹ️ Nhiệm vụ này đã được xác nhận trước đó.</h2>');
        if(a.status==='cancelled')return res.status(410).send('<h2>❌ Nhiệm vụ này đã bị hủy. Vui lòng nhận nhiệm vụ mới.</h2>');
        if(a.status==='expired'||linkTaskAttemptIsExpired(a)){
            if(linkTaskAttemptIsActive(a)){
                await db.from('link_task_attempts').update({status:'expired'}).eq('id',a.id).in('status',LINK_TASK_ACTIVE_STATUSES);
            }
            return res.status(410).send('<h2>⌛ NHIỆM VỤ ĐÃ HẾT HẠN</h2><p>Bạn đã vượt quá thời gian 10 phút. Vui lòng quay lại Mini App và nhận nhiệm vụ mới.</p>');
        }
        if(!linkTaskAttemptIsActive(a))return res.status(409).send('<h2>❌ Nhiệm vụ không còn ở trạng thái có thể xác nhận.</h2>');
        if(!isMobileUserAgent(req))return res.status(403).send('<h2>📱 Chỉ hỗ trợ hoàn thành nhiệm vụ trên điện thoại.</h2>');

        const landingIp=requestIp(req);
        if(linkTaskNeedsRequestIp(cfg)&&!landingIp){
            return res.status(503).send('<h2>⚠️ Tạm thời chưa xác định được IP kết nối. Vui lòng thử lại sau.</h2>');
        }
        const landingIpHash=landingIp?hashNetworkValue(landingIp,'ip'):'';
        if((linkTaskNeedsRequestIp(cfg)&&!landingIpHash)||!a.device_hash){
            return res.status(503).send('<h2>⚠️ Hệ thống xác minh lượt nhiệm vụ đang tạm thời chưa sẵn sàng.</h2>');
        }
        const deviceIpHash=a.device_hash&&landingIpHash?hashNetworkValue(`${a.device_hash}:${landingIpHash}`,'device-ip'):'';
        const nowIso=new Date().toISOString();
        const {data:landed,error:ue}=await db.from('link_task_attempts').update({
            status:'landed',landing_ip_hash:landingIpHash||null,device_ip_hash:deviceIpHash||null,
            country_code:null,is_vpn:false,landed_at:nowIso
        })
            .eq('id',a.id)
            .in('status',LINK_TASK_ACTIVE_STATUSES)
            .gt('expires_at',nowIso)
            .select('*').maybeSingle();
        if(ue)throw ue;
        if(!landed){
            const {data:fresh,error:freshError}=await db.from('link_task_attempts').select('status,expires_at').eq('id',a.id).maybeSingle();
            if(freshError)throw freshError;
            if(fresh?.status==='cancelled')return res.status(410).send('<h2>❌ Nhiệm vụ này đã bị hủy. Vui lòng nhận nhiệm vụ mới.</h2>');
            if(fresh?.status==='expired'||!fresh?.expires_at||new Date(fresh.expires_at).getTime()<=Date.now()){
                if(fresh?.status!=='rewarded')await db.from('link_task_attempts').update({status:'expired'}).eq('id',a.id).in('status',LINK_TASK_ACTIVE_STATUSES);
                return res.status(410).send('<h2>⌛ NHIỆM VỤ ĐÃ HẾT HẠN</h2><p>Bạn đã vượt quá thời gian 10 phút. Vui lòng quay lại Mini App và nhận nhiệm vụ mới.</p>');
            }
            return res.status(409).send('<h2>❌ Nhiệm vụ đã thay đổi trạng thái. Vui lòng quay lại Mini App kiểm tra.</h2>');
        }

        const verificationCode=linkTaskVerificationCode(landed);
        if(!verificationCode)return res.status(503).send('<h2>⚠️ Hệ thống mã xác nhận chưa sẵn sàng.</h2>');
        res.set('Cache-Control','no-store, no-cache, must-revalidate');
        return res.send(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mã xác nhận nhiệm vụ</title><style>body{font-family:system-ui;background:linear-gradient(180deg,#07111f,#0f172a);color:#fff;display:grid;place-items:center;min-height:100vh;margin:0;padding:20px}.c{width:min(420px,100%);box-sizing:border-box;text-align:center;background:#1e293b;border:1px solid #334155;border-radius:24px;padding:24px;box-shadow:0 18px 50px rgba(0,0,0,.35)}.code{font-size:40px;letter-spacing:10px;font-weight:900;color:#fbbf24;background:#0f172a;border:1px solid #475569;border-radius:16px;padding:14px 8px;margin:14px 0}.b{display:block;width:100%;box-sizing:border-box;border:0;margin-top:12px;padding:14px 18px;border-radius:14px;background:#2563eb;color:#fff;text-decoration:none;font-weight:900;font-size:14px}.b2{background:#0f766e}.s{color:#cbd5e1;font-size:13px;line-height:1.55}.ok{color:#86efac}.hint{color:#94a3b8;font-size:12px;margin-top:14px}</style></head><body><div class="c"><div style="font-size:48px">✅</div><h2 class="ok">VƯỢT LINK THÀNH CÔNG</h2><p class="s">🔐 MÃ XÁC NHẬN CỦA BẠN</p><div id="code" class="code">${safeHtml(verificationCode)}</div><button class="b" onclick="copyCode()">📋 SAO CHÉP MÃ</button><a class="b b2" href="${safeHtml(telegramMiniAppDeepLink('linktask'))}">🚀 QUAY LẠI MINI APP</a><a class="b" href="${safeHtml(telegramBotDeepLink())}" style="background:#334155">🤖 MỞ BOT TELEGRAM</a><p class="hint">Quay lại Mini App → Nhiệm vụ → nhập mã này vào đúng nhiệm vụ vừa làm trước khi hết 10 phút để nhận <b>${Number(cfg.rewardOrders).toLocaleString('vi-VN')} Đơn Hàng</b>.</p></div><script>function copyCode(){var c=document.getElementById('code').textContent.trim();if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(c).then(function(){alert('✅ Đã sao chép mã: '+c);}).catch(function(){fallback(c);});}else{fallback(c);}}function fallback(c){var t=document.createElement('textarea');t.value=c;document.body.appendChild(t);t.select();try{document.execCommand('copy');alert('✅ Đã sao chép mã: '+c);}catch(e){alert('Mã của bạn: '+c);}document.body.removeChild(t);}</script></body></html>`);
    }catch(e){
        console.error('Link task landing:',e?.message||e);
        return res.status(500).send('<h2>⚠️ Không thể xác nhận nhiệm vụ lúc này.</h2>');
    }finally{
        if(release){try{await release();}catch(_){}}
    }
});
app.post('/api/link-task/verify-code',async(req,res)=>{
    const userId=String(req.body?.userId||''),taskId=String(req.body?.taskId||''),submittedCode=String(req.body?.code||'').trim();
    if(!assertTelegramUser(req,userId))return res.status(401).json({success:false,code:'auth_failed',error:'Telegram session không hợp lệ.'});
    if(!requireTelegramMobile(req,res))return;
    const cfg=LINK_TASK_CONFIG[taskId];
    if(!cfg)return res.status(400).json({success:false,code:'provider_unsupported',error:'Nhiệm vụ vượt link không hợp lệ.'});
    // Kể cả payload không đủ 6 số cũng đi qua RPC với p_code_valid=false để mọi lần thử đều chịu cooldown server-side.
    const submittedCodeFormatValid=/^\d{6}$/.test(submittedCode);
    try{
        const dbReadiness=await checkLinkTaskDatabaseReadiness();
        if(!dbReadiness.ready){
            return res.status(503).json({success:false,code:dbReadiness.code||'link_task_db_not_ready',error:dbReadiness.safeReason||'Hệ thống nhiệm vụ đang được hoàn tất cấu hình dữ liệu. Vui lòng thử lại sau.'});
        }
        const db=linkTaskDb();
        const {data:attempt,error:attemptError}=await db.from('link_task_attempts').select('*')
            .eq('user_id',userId).eq('task_id',taskId)
            .order('created_at',{ascending:false}).limit(1).maybeSingle();
        if(attemptError)throw attemptError;
        if(!attempt)return res.status(409).json({success:false,code:'not_landed',error:'Chưa xác nhận hoàn thành quá trình vượt link.'});
        if(attempt.status==='cancelled'){
            return res.status(410).json({success:false,code:'cancelled',error:'Nhiệm vụ này đã bị hủy. Mã/link cũ không còn được tính.'});
        }
        if(attempt.status==='expired'||(attempt.status!=='rewarded' && (!attempt.expires_at || new Date(attempt.expires_at).getTime()<=Date.now()))){
            if(attempt.status!=='expired'){
                await db.from('link_task_attempts').update({status:'expired'}).eq('id',attempt.id).in('status',LINK_TASK_ACTIVE_STATUSES);
            }
            return res.status(410).json({success:false,code:'expired',error:'Nhiệm vụ đã hết thời gian 10 phút. Vui lòng nhận nhiệm vụ mới.'});
        }
        if(attempt.status!=='landed' && attempt.status!=='rewarded'){
            return res.status(409).json({success:false,code:'not_landed',error:'Chưa xác nhận hoàn thành quá trình vượt link.'});
        }
        const expectedCode=linkTaskVerificationCode(attempt);
        const codeValid=submittedCodeFormatValid && /^\d{6}$/.test(expectedCode) && timingSafeEqualDigits(submittedCode,expectedCode);
        const {data:rpc,error:rpcError}=await db.rpc('link_task_verify_code_atomic',{
            p_nonce:String(attempt.nonce||''),p_user_id:userId,p_code_valid:codeValid,
            p_quota_type:cfg.quotaType,p_window_start:new Date(Date.now()-LINK_TASK_ROLLING_MS).toISOString(),p_day_key:vietnamDayKey(),
            p_max_ip:cfg.maxPerIp,p_max_device:cfg.maxPerDevice,p_max_device_ip:cfg.maxPerDeviceIp||0
        });
        if(rpcError)throw rpcError;
        const result=Array.isArray(rpc)?rpc[0]:rpc;
        if(!result?.ok){
            const code=String(result?.code||'verify_failed');
            if(code==='code_cooldown')return res.status(429).json({success:false,cooldown:true,code,retryAfterMs:Math.max(1,Number(result?.retry_after_ms||LINK_TASK_CODE_COOLDOWN_MS)),error:'Vui lòng chờ đủ 7 giây trước khi thử mã tiếp theo.'});
            if(code==='invalid_code')return res.status(400).json({success:false,cooldown:true,code,retryAfterMs:Math.max(1,Number(result?.retry_after_ms||LINK_TASK_CODE_COOLDOWN_MS)),error:'Mã xác nhận không đúng.'});
            if(code==='expired')return res.status(410).json({success:false,code,error:'Nhiệm vụ đã hết thời gian 10 phút. Vui lòng nhận nhiệm vụ mới.'});
            if(code==='not_landed'||code==='not_found')return res.status(409).json({success:false,code:'not_landed',error:'Chưa xác nhận hoàn thành quá trình vượt link.'});
            if(code==='wrong_user')return res.status(403).json({success:false,code,error:'Mã xác nhận không thuộc tài khoản này.'});
            if(code==='ip_limit')return res.status(429).json({success:false,code,error:'IP này đã hết lượt nhận thưởng cho nhiệm vụ.'});
            if(code==='device_limit')return res.status(429).json({success:false,code,error:'Thiết bị này đã hết lượt nhận thưởng cho nhiệm vụ.'});
            if(code==='device_ip_limit')return res.status(429).json({success:false,code,error:'Cặp thiết bị/IP này đã hết lượt nhận thưởng cho nhiệm vụ.'});
            return res.status(409).json({success:false,code,error:'Chưa thể xác nhận nhiệm vụ. Vui lòng thử lại.'});
        }
        if(!result.idempotent){
            await recordAntiFraudEvent(userId,'link-task',{rewardEvent:true,orders:Number(result.reward_orders||cfg.rewardOrders)});
            logTransaction(userId,'orders',Number(result.reward_orders||cfg.rewardOrders),`Vượt link ${cfg.provider}`);
        }
        const fresh=await readUserRow(userId);
        const freshUser=fresh?.data||{};
        return res.json({
            success:true,idempotent:!!result.idempotent,taskId,taskStatus:'rewarded',
            rewardOrders:Number(result.reward_orders||cfg.rewardOrders),orders:Number(result.orders??freshUser.orders??0),
            walletUpdatedAt:freshUser.walletUpdatedAt||null
        });
    }catch(e){
        console.error('Link task verify code:',linkTaskDbDiagnosticCode(e),e?.message||e);
        const dbState=linkTaskDbErrorState(e);if(dbState)linkTaskDbReadinessCache=null;
        return res.status(503).json({success:false,code:dbState?.code||'database_error',error:dbState?.message||'Không thể xác nhận mã lúc này. Vui lòng thử lại sau.'});
    }
});

async function handleLinkTaskBotConfirmation(ctx,nonce){
    const userId=String(ctx.from?.id||''),token=String(nonce||'');
    if(!userId||!token)return ctx.reply('❌ Link xác nhận không hợp lệ hoặc đã hết hạn.');
    try{
        const db=linkTaskDb();
        const {data:a,error}=await db.from('link_task_attempts').select('user_id,task_id,status,expires_at,landed_at').eq('nonce',token).maybeSingle();
        if(error||!a)return ctx.reply('❌ Link xác nhận không hợp lệ hoặc đã hết hạn.');
        if(String(a.user_id)!==userId)return ctx.reply('❌ Link xác nhận này thuộc về tài khoản Telegram khác.');
        if(a.status==='rewarded')return ctx.reply('ℹ️ Nhiệm vụ này đã được xác nhận trước đó. Không có phần thưởng nào được cộng thêm.');
        if(a.status==='cancelled')return ctx.reply('❌ Nhiệm vụ này đã bị hủy. Mã/link cũ không còn được tính.');
        if(a.status==='expired'||!a.expires_at||new Date(a.expires_at).getTime()<=Date.now())return ctx.reply('❌ Nhiệm vụ đã hết thời gian 10 phút. Vui lòng nhận nhiệm vụ mới.');
        if(a.status!=='landed'||!a.landed_at)return ctx.reply('❌ Chưa xác nhận hoàn thành quá trình vượt link.');
        return ctx.reply('✅ Link của bạn đã được ghi nhận.\n\n🔐 Flow xác nhận hiện tại: quay lại Mini App → Nhiệm vụ → nhập mã 6 số đã hiển thị ở trang sau khi vượt link để nhận thưởng.');
    }catch(e){console.error('Link task bot confirm legacy:',e?.message||e);return ctx.reply('⚠️ Không thể kiểm tra nhiệm vụ lúc này. Vui lòng thử lại sau.');}
}
