        const token=String(req.query.ymid||''),eventType=String(req.query.event_type||'').toLowerCase(),zoneId=String(req.query.zone_id||'');if(!token||!['impression','click'].includes(eventType))return res.status(400).send('bad request');if(MONETAG_ZONE_ID&&zoneId&&zoneId!==MONETAG_ZONE_ID)return res.status(400).send('zone mismatch');
        const session=await readPersistentEvent(persistentEventKey('ad-session',token));if(!session)return res.status(404).send('unknown session');
